import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../../config/api';
import { vendorConfirm, vendorAlert } from './VendorConfirm';
import { 
  Building2, 
  Users, 
  MessageCircle, 
  Video, 
  Package,
  TrendingUp,
  Activity,
  Settings,
  UserPlus,
  Shield,
  CheckCircle,
  XCircle
} from 'lucide-react';

/**
 * Vendor Dashboard Page
 * Shows tenant/ RT/RW management overview
 */
const VendorDashboard = () => {
  const [tenants, setTenants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [stats, setStats] = useState({
    total: 0,
    active: 0,
    suspended: 0
  });

  useEffect(() => {
    loadTenants();
  }, []);

  const loadTenants = async () => {
    const token = localStorage.getItem('vendor_token');
    if (!token) {
      setError('Session berakhir. Silakan login kembali.');
      setLoading(false);
      return;
    }

    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants`, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.detail || 'Gagal memuat data');
      }

      const data = await res.json();
      setTenants(data);
      
      // Calculate stats
      const active = data.filter(t => t.status === 'active').length;
      setStats({
        total: data.length,
        active: active,
        suspended: data.length - active
      });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (tenantId, newStatus) => {
    if (!await vendorConfirm(`${newStatus === 'suspended' ? 'Suspend' : 'Aktifkan'} tenant ini?`, newStatus === 'suspended' ? 'Suspend Tenant' : 'Aktifkan Tenant')) return;
    
    const token = localStorage.getItem('vendor_token');
    
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants/${tenantId}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ status: newStatus })
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.detail || 'Gagal mengubah status');
      }

      // Refresh data
      loadTenants();
    } catch (err) {
      vendorAlert(err.message, 'Gagal');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-12 h-12 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 ">Dashboard Vendor</h1>
          <p className="text-gray-500 ">Kelola Tenant RT/RW</p>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white  rounded-xl p-6 border border-gray-200 ">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 ">Total Tenant</p>
              <p className="text-3xl font-bold text-gray-800 ">{stats.total}</p>
            </div>
            <div className="w-12 h-12 bg-[#ed6f5c] rounded-lg flex items-center justify-center">
              <Building2 className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>

        <div className="bg-white  rounded-xl p-6 border border-gray-200 ">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 ">Tenant Aktif</p>
              <p className="text-3xl font-bold text-emerald-600">{stats.active}</p>
            </div>
            <div className="w-12 h-12 bg-emerald-100 rounded-lg flex items-center justify-center">
              <CheckCircle className="w-6 h-6 text-emerald-600 " />
            </div>
          </div>
        </div>

        <div className="bg-white  rounded-xl p-6 border border-gray-200 ">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 ">Tenant Suspended</p>
              <p className="text-3xl font-bold text-red-600">{stats.suspended}</p>
            </div>
            <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center">
              <XCircle className="w-6 h-6 text-red-600 " />
            </div>
          </div>
        </div>
      </div>

      {/* Tenant List */}
      <div className="bg-white  rounded-xl border border-gray-200  overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200 ">
          <h2 className="text-lg font-semibold text-gray-800 ">Daftar Tenant</h2>
        </div>
        
        {error && (
          <div className="px-6 py-4 bg-red-50 border-b border-red-200 ">
            <p className="text-red-600 ">{error}</p>
          </div>
        )}

        {tenants.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <Building2 className="w-12 h-12 text-gray-300  mx-auto mb-4" />
            <p className="text-gray-500 ">Belum ada tenant</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-semibold text-gray-500  uppercase">Nama</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold text-gray-500  uppercase">Tipe</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold text-gray-500  uppercase">Alamat</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold text-gray-500  uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold text-gray-500  uppercase">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {tenants.map((tenant) => (
                  <tr key={tenant.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <p className="font-medium text-gray-800 ">{tenant.name}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 ">
                        {tenant.tenant_type}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-sm text-gray-600 ">
                        {tenant.address || '-'}
                      </p>
                      {tenant.city && (
                        <p className="text-xs text-gray-400 ">
                          {tenant.city}, {tenant.province}
                        </p>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        tenant.status === 'active' 
                          ? 'bg-emerald-100 text-emerald-800 '
                          : 'bg-red-100 text-red-800 '
                      }`}>
                        {tenant.status === 'active' ? 'Aktif' : 'Suspended'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <button
                        onClick={() => handleStatusChange(tenant.id, tenant.status === 'active' ? 'suspended' : 'active')}
                        className={`text-sm font-medium ${
                          tenant.status === 'active'
                            ? 'text-red-600 hover:text-red-800 '
                            : 'text-emerald-600 hover:text-emerald-800 '
                        }`}
                      >
                        {tenant.status === 'active' ? 'Suspend' : 'Aktifkan'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorDashboard;

