import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { API_BASE_URL } from '@/config/api';

const fmt = (iso) => {
  if (!iso) return '-';
  const d = new Date(iso);
  const months = ['Januari','Februari','Maret','April','Mei','Juni',
                  'Juli','Agustus','September','Oktober','November','Desember'];
  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
};

export default function VerifySurat() {
  const { id } = useParams();
  const [status, setStatus] = useState('loading');
  const [data, setData] = useState(null);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/surat-resmi/verify/${id}`)
      .then(r => {
        if (!r.ok) return Promise.reject(r.status);
        return r.json();
      })
      .then(d => { setData(d); setStatus('valid'); })
      .catch(code => setStatus(code === 404 ? 'invalid' : 'error'));
  }, [id]);

  return (
    <div style={{ minHeight: '100vh', background: '#f3f4f6', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '24px 16px' }}>
      <div style={{ width: '100%', maxWidth: '440px', background: '#fff', borderRadius: '16px', boxShadow: '0 4px 24px rgba(0,0,0,0.10)', overflow: 'hidden' }}>

        {/* Header */}
        <div style={{ background: '#1e3a5f', padding: '20px 24px', textAlign: 'center' }}>
          <div style={{ color: '#fff', fontWeight: 700, fontSize: '18px', letterSpacing: '0.5px' }}>
            Ruang Warga
          </div>
          <div style={{ color: '#93c5fd', fontSize: '13px', marginTop: '2px' }}>
            Sistem Verifikasi Surat Resmi
          </div>
        </div>

        {/* Body */}
        <div style={{ padding: '28px 24px' }}>

          {status === 'loading' && (
            <div style={{ textAlign: 'center', padding: '32px 0' }}>
              <div style={{ width: '40px', height: '40px', border: '4px solid #e5e7eb', borderTopColor: '#3b82f6', borderRadius: '50%', animation: 'spin 0.8s linear infinite', margin: '0 auto 16px' }} />
              <p style={{ color: '#6b7280', fontSize: '14px' }}>Memverifikasi surat...</p>
              <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
            </div>
          )}

          {status === 'valid' && data && (
            <>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', background: '#f0fdf4', border: '1px solid #86efac', borderRadius: '10px', padding: '14px 16px', marginBottom: '24px' }}>
                <span style={{ fontSize: '24px' }}>✅</span>
                <div>
                  <div style={{ fontWeight: 700, color: '#15803d', fontSize: '15px' }}>Surat Valid</div>
                  <div style={{ color: '#16a34a', fontSize: '13px' }}>Dokumen ini terverifikasi resmi</div>
                </div>
              </div>

              {/* Penerbit */}
              <div style={{ background: '#eff6ff', border: '1px solid #bfdbfe', borderRadius: '8px', padding: '10px 14px', marginBottom: '16px', fontSize: '13px' }}>
                <div style={{ color: '#1e40af', fontWeight: 700, marginBottom: '2px' }}>
                  RT {data.no_rt || '-'} / RW {data.no_rw || '-'}
                  {data.nama_kelurahan ? ` — Kel. ${data.nama_kelurahan}` : ''}
                  {data.kecamatan ? `, Kec. ${data.kecamatan}` : ''}
                </div>
                <div style={{ color: '#3b82f6' }}>
                  {data.jabatan || ''}{data.nama_pejabat ? `: ${data.nama_pejabat}` : ''}
                </div>
              </div>

              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
                <tbody>
                  {[
                    ['Nomor Surat', data.nomor_surat || '-'],
                    ['Jenis Surat', data.jenis_surat || '-'],
                    ['Atas Nama', data.pemohon_nama || '-'],
                    ['Tanggal Terbit', fmt(data.issued_at)],
                    ['Status', 'Telah Diterbitkan'],
                  ].map(([label, value]) => (
                    <tr key={label} style={{ borderBottom: '1px solid #f3f4f6' }}>
                      <td style={{ padding: '10px 0', color: '#6b7280', width: '40%', verticalAlign: 'top' }}>{label}</td>
                      <td style={{ padding: '10px 0', fontWeight: 600, color: '#111827' }}>{value}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {status === 'invalid' && (
            <div style={{ textAlign: 'center', padding: '24px 0' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', background: '#fef2f2', border: '1px solid #fca5a5', borderRadius: '10px', padding: '14px 16px', marginBottom: '16px' }}>
                <span style={{ fontSize: '24px' }}>❌</span>
                <div style={{ textAlign: 'left' }}>
                  <div style={{ fontWeight: 700, color: '#dc2626', fontSize: '15px' }}>Surat Tidak Valid</div>
                  <div style={{ color: '#ef4444', fontSize: '13px' }}>Dokumen tidak ditemukan atau belum diterbitkan</div>
                </div>
              </div>
              <p style={{ color: '#6b7280', fontSize: '13px' }}>Pastikan Anda memindai QR code yang benar dari dokumen resmi.</p>
            </div>
          )}

          {status === 'error' && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', background: '#fffbeb', border: '1px solid #fcd34d', borderRadius: '10px', padding: '14px 16px' }}>
              <span style={{ fontSize: '24px' }}>⚠️</span>
              <div>
                <div style={{ fontWeight: 700, color: '#92400e', fontSize: '15px' }}>Gagal Memverifikasi</div>
                <div style={{ color: '#b45309', fontSize: '13px' }}>Terjadi kesalahan, coba lagi beberapa saat.</div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{ background: '#f9fafb', borderTop: '1px solid #e5e7eb', padding: '12px 24px', textAlign: 'center', color: '#9ca3af', fontSize: '12px' }}>
          Verifikasi otomatis oleh sistem Ruang Warga
        </div>
      </div>
    </div>
  );
}
