import { useEffect, useState, useMemo } from "react";
import { API_ENDPOINTS } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
  AlertDialogDescription,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { Pencil, Trash2, Plus } from "lucide-react";

export default function THRPage() {
  const [thrs, setThrs] = useState([]);
  const [stats, setStats] = useState(null);
  const [search, setSearch] = useState("");
  // IPL bills (to compute collected months)
  const [iplBills, setIplBills] = useState([]);
  const { token, user, logout } = useAuth();
  const { canCreate, canEdit, canDelete } = useRolePermissions(user?.role, token);

  // FORM DIALOG
  const [openForm, setOpenForm] = useState(false);
  const [formData, setFormData] = useState({
    id: null,
    nama: "",
    nominal_target: "",
    deskripsi: "",
    periode: "Tahunan",
  });

  // DELETE DIALOG
  const [openDelete, setOpenDelete] = useState(false);
  const [deleteId, setDeleteId] = useState(null);

  // POSTING DIALOG
  const [openPosting, setOpenPosting] = useState(false);
  const [postingData, setPostingData] = useState({
    thr_id: "",
    bulan: new Date().getMonth() + 1,
    nominal: "",
    keterangan: "",
  });

  // GENERATE POSTING (batch for all THR)
  const [openGenerate, setOpenGenerate] = useState(false);
  const [generateResult, setGenerateResult] = useState(null);

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(25);

  // LOAD THR DATA
  const loadTHR = async () => {
    try {
      const res = await fetch(API_ENDPOINTS.THR, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setThrs(data);
    } catch (err) {
      console.error("Error loading THR:", err);
      toast.error("Gagal memuat data THR");
    }
  };

  // LOAD STATS
  const loadStats = async () => {
    try {
      const res = await fetch(API_ENDPOINTS.THR_STATS, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setStats(data);
      }
    } catch (err) {
      console.error("Error loading stats:", err);
    }
  };

  // LOAD IPL BILLS (to count paid bills)
  const loadIplBills = async () => {
    try {
      const res = await fetch(API_ENDPOINTS.IPL_BILLS, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setIplBills(data);
      }
    } catch (err) {
      console.error("Error loading IPL bills:", err);
    }
  };

  useEffect(() => {
    loadTHR();
    loadStats();
    loadIplBills();
  }, [token, user]);

  // FILTER LOGIC
  const filtered = thrs.filter((t) =>
    t.nama.toLowerCase().includes(search.toLowerCase())
  );

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // FORMAT RUPIAH
  const formatRupiah = (value) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(value || 0);
  };

  // FORMAT FOR INPUT (no prefix, just grouping)
  const formatInputNumber = (value) => {
    if (value === null || value === undefined || value === "") return "";
    const n = Number(value) || 0;
    return n.toLocaleString("id-ID");
  };

  const removeFormatting = (value) => {
    if (!value) return "";
    return value.toString().replace(/[^0-9]/g, "");
  };

  // HANDLE SAVE
  const handleSave = async () => {
    if (!formData.nama || !formData.nominal_target) {
      toast.error("Nama dan Nominal Target harus diisi");
      return;
    }

    if (!canCreate("thr")) {
      toast.error("Anda tidak memiliki izin untuk membuat THR");
      return;
    }

    try {
      const url = formData.id
        ? `${API_ENDPOINTS.THR}/${formData.id}`
        : API_ENDPOINTS.THR;

      const method = formData.id ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          nama: formData.nama,
          nominal_target: parseFloat(formData.nominal_target),
          deskripsi: formData.deskripsi,
          periode: formData.periode,
        }),
      });

      if (res.ok) {
        toast.success(
          `THR berhasil ${formData.id ? "diupdate" : "ditambahkan"}`
        );
        loadTHR();
        loadStats();
        setOpenForm(false);
        resetForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menyimpan THR");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menyimpan");
    }
  };

  // HANDLE DELETE
  const handleDelete = async () => {
    if (!canDelete("thr")) {
      toast.error("Anda tidak memiliki izin untuk menghapus THR");
      return;
    }

    try {
      const res = await fetch(`${API_ENDPOINTS.THR}/${deleteId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        toast.success("THR berhasil dihapus");
        loadTHR();
        loadStats();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menghapus THR");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menghapus");
    } finally {
      setOpenDelete(false);
      setDeleteId(null);
    }
  };

  // HANDLE POSTING
  const handlePosting = async () => {
    if (!postingData.thr_id || !postingData.nominal) {
      toast.error("THR dan Nominal harus diisi");
      return;
    }

    if (!canCreate("thr")) {
      toast.error("Anda tidak memiliki izin untuk posting THR");
      return;
    }

    try {
      const res = await fetch(API_ENDPOINTS.THR_POSTING, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          thr_id: postingData.thr_id,
          bulan: parseInt(postingData.bulan),
          nominal: parseFloat(postingData.nominal),
          keterangan: postingData.keterangan,
        }),
      });

      if (res.ok) {
        toast.success("THR berhasil diposting ke Keuangan");
        loadTHR();
        loadStats();
        setOpenPosting(false);
        resetPostingForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal posting THR");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat posting");
    }
  };

  const resetForm = () => {
    setFormData({
      id: null,
      nama: "",
      nominal_target: "",
      deskripsi: "",
      periode: "Bulanan",
    });
  };

  const resetPostingForm = () => {
    setPostingData({
      thr_id: "",
      bulan: new Date().getMonth() + 1,
      nominal: "",
      keterangan: "",
    });
  };

  const openEditForm = (item) => {
    setFormData({
      id: item.id,
      nama: item.nama,
      nominal_target: item.nominal_target.toString(),
      deskripsi: item.deskripsi || "",
      periode: item.periode,
    });
    setOpenForm(true);
  };

  const openDeleteDialog = (id) => {
    setDeleteId(id);
    setOpenDelete(true);
  };

  // CARD BOX CALCULATIONS (per requested formulas)
  const totalTargetTHR = stats?.total_target || 0;
  const totalPerBulan = totalTargetTHR ? totalTargetTHR / 12 : 0;
  const rumahCount = stats?.rumah_count || 1;

  // Iuran THR per Rumah/Bulan = (Target THR per Bulan) / jumlah rumah
  const iuranPerRumah = rumahCount > 0 ? totalPerBulan / rumahCount : 0;

  // Total Iuran THR Terkumpul = jumlah IPL yang berstatus 'Lunas' × iuranPerRumah
  const paidIplCount = iplBills.filter((b) => (b.status || '').toLowerCase() === 'lunas').length;
  const totalIuranTerkumpul = paidIplCount * iuranPerRumah;

  // Persentase = (Total Iuran THR Terkumpul / Total Target THR) × 100%
  const statusPencapaian = totalTargetTHR > 0 ? (totalIuranTerkumpul / totalTargetTHR) * 100 : 0;

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      <div className="flex justify-between items-center mb-6">
         <div>
        <h1 className="text-3xl font-bold dark:text-gray-100">Biaya THR</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Kelola biaya THR tahunan
          </p>
          </div>
        {canCreate("thr") && (
          <div className="flex gap-2">
            <Button
              onClick={() => {
                resetForm();
                setOpenForm(true);
              }}
              className="bg-[#ed6f5c] hover:bg-[#e05544]"
            >
              <Plus className="w-4 h-4 mr-2" />
              Tambah THR
            </Button>
            <Button
              onClick={() => setOpenGenerate(true)}
              className="bg-green-600 hover:bg-green-700"
            >
              Posting Biaya THR
            </Button>
          </div>
        )}
      </div>

      {/* CARD BOXES - match Laporan/Report summary card pattern */}
      {/** Build summary cards similar to `LaporanKeuangan` */}
      {useMemo(() => {
        return (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4 xl:grid-cols-4 mb-8">
            {[
              {
                label: 'Total Target THR',
                value: totalTargetTHR,
                description: `${thrs.filter((t) => t.status === 'aktif').length} dari ${thrs.length} item aktif`,
                accent: 'text-amber-600',
              },
              {
                label: 'Target THR per Bulan',
                value: totalPerBulan,
                description: 'Total target dibagi 12 bulan',
                accent: 'text-slate-600',
              },
              {
                label: 'Iuran THR per Rumah/Bulan',
                value: iuranPerRumah,
                description: 'Iuran per rumah setiap bulan',
                accent: 'text-emerald-600',
              },
              {
                label: 'Total Iuran THR Terkumpul',
                value: totalIuranTerkumpul,
                description: `${paidIplCount} IPL terbayar`,
                accent: 'text-slate-600',
                isStatus: true,
              },
            ].map((card) => (
              <Card key={card.label} className="border-l-4 border-l-yellow-500 bg-white dark:bg-slate-800">
                <CardHeader>
                  <CardTitle className="text-sm text-gray-500 dark:text-gray-300">{card.label}</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className={`text-2xl font-bold ${card.accent}`}>{formatRupiah(card.value)}</p>
                  <p className="text-xs text-gray-500 dark:text-gray-400">{card.description}</p>
                  {card.isStatus && (
                    <p className="mt-3 text-sm text-gray-600 dark:text-gray-300 font-semibold">Status: {statusPencapaian.toFixed(2)}%</p>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        );
      }, [totalTargetTHR, totalPerBulan, iuranPerRumah, totalIuranTerkumpul, paidIplCount, statusPencapaian, thrs])}

      {/* SEARCH */}
      <div className="mb-4">
        <Input
          type="text"
          placeholder="Cari nama penerima THR..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="w-full bg-[#f7f1de] dark:bg-gray-800"
        />
      </div>

      {/* TABLE */}
      <div className="border rounded-lg overflow-hidden bg-[#f7f1de] dark:bg-gray-800 dark:border-gray-700">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-100 dark:bg-gray-800">
              <TableHead className="dark:text-gray-200">Nama Penerima THR</TableHead>
              <TableHead className="dark:text-gray-200">Nominal Target</TableHead>
              <TableHead className="dark:text-gray-200">Periode</TableHead>
              <TableHead className="dark:text-gray-200">Status</TableHead>
              <TableHead className="dark:text-gray-200">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length > 0 ? (
              paginatedData.map((item) => (
                <TableRow key={item.id}>
                  <TableCell>{item.nama}</TableCell>
                  <TableCell>{formatRupiah(item.nominal_target)}</TableCell>
                  <TableCell>{item.periode}</TableCell>
                  <TableCell>
                    <span className="px-2 py-1 rounded-full text-xs font-semibold bg-green-100 text-green-800">
                      {item.status}
                    </span>
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-2">
                      {canEdit("thr") && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => openEditForm(item)}
                        >
                          <Pencil className="w-4 h-4" />
                        </Button>
                      )}
                      {canDelete("thr") && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => openDeleteDialog(item.id)}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan="5" className="text-center text-gray-500 py-8">
                  Tidak ada data THR
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      {/* PAGINATION */}
      {totalPages > 1 && (
        <div className="flex justify-between items-center mt-4">
          <div className="text-sm text-gray-600">
            Halaman {page} dari {totalPages}
          </div>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              onClick={() => setPage(Math.max(1, page - 1))}
              disabled={page === 1}
            >
              Sebelumnya
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => setPage(Math.min(totalPages, page + 1))}
              disabled={page === totalPages}
            >
              Berikutnya
            </Button>
          </div>
        </div>
      )}

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {formData.id ? "Edit THR" : "Tambah THR Baru"}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label>Nama Penerima THR</Label>
              <Input
                value={formData.nama}
                onChange={(e) =>
                  setFormData({ ...formData, nama: e.target.value })
                }
                placeholder="Contoh: THR 2025 Karyawan"
              />
            </div>

            <div>
              <Label>Nominal Target</Label>
              <Input
                type="text"
                value={formatInputNumber(formData.nominal_target)}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    nominal_target: Number(removeFormatting(e.target.value)) || 0,
                  })
                }
                placeholder="0"
              />
            </div>

            <div>
              <Label>Periode</Label>
              <Select
                value={formData.periode}
                onValueChange={(value) =>
                  setFormData({ ...formData, periode: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Bulanan">Bulanan</SelectItem>
                  <SelectItem value="Tahunan">Tahunan</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label>Deskripsi</Label>
              <Input
                value={formData.deskripsi}
                onChange={(e) =>
                  setFormData({ ...formData, deskripsi: e.target.value })
                }
                placeholder="Deskripsi THR"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenForm(false)}>
              Batal
            </Button>
            <Button onClick={handleSave} className="bg-[#ed6f5c] hover:bg-[#e05544]">
              Simpan
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* DELETE DIALOG */}
      <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus THR</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus THR ini? Tindakan ini tidak dapat
              dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* POSTING DIALOG (manual) - kept for backward compatibility */}
      <Dialog open={openPosting} onOpenChange={setOpenPosting}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Posting Biaya THR (Manual)</DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label>Pilih THR</Label>
              <Select
                value={postingData.thr_id}
                onValueChange={(value) =>
                  setPostingData({ ...postingData, thr_id: value })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Pilih THR" />
                </SelectTrigger>
                <SelectContent>
                  {thrs.map((thr) => (
                    <SelectItem key={thr.id} value={thr.id}>
                      {thr.nama}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label>Bulan</Label>
              <Select
                value={postingData.bulan.toString()}
                onValueChange={(value) =>
                  setPostingData({
                    ...postingData,
                    bulan: parseInt(value),
                  })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Array.from({ length: 12 }, (_, i) => i + 1).map((m) => (
                    <SelectItem key={m} value={m.toString()}>
                      {new Date(2024, m - 1).toLocaleString("id-ID", {
                        month: "long",
                      })}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label>Nominal</Label>
              <Input
                type="text"
                value={formatInputNumber(postingData.nominal)}
                onChange={(e) =>
                  setPostingData({
                    ...postingData,
                    nominal: Number(removeFormatting(e.target.value)) || 0,
                  })
                }
                placeholder="0"
              />
            </div>

            <div>
              <Label>Keterangan</Label>
              <Input
                value={postingData.keterangan}
                onChange={(e) =>
                  setPostingData({
                    ...postingData,
                    keterangan: e.target.value,
                  })
                }
                placeholder="Keterangan posting"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenPosting(false)}>
              Batal
            </Button>
            <Button
              onClick={handlePosting}
              className="bg-green-600 hover:bg-green-700"
            >
              Posting
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* GENERATE DIALOG - Batch posting mirip Biaya Rutin */}
      <AlertDialog open={openGenerate} onOpenChange={setOpenGenerate}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Posting Biaya THR Tahunan</AlertDialogTitle>
            <AlertDialogDescription>
              Sistem akan membuat transaksi pengeluaran untuk semua THR yang aktif.
              Pastikan data THR sudah benar sebelum melanjutkan.
            </AlertDialogDescription>
          </AlertDialogHeader>

          <AlertDialogFooter>
            <AlertDialogCancel>Tutup</AlertDialogCancel>
            <AlertDialogAction
              onClick={async () => {
                try {
                  const res = await fetch(`${API_ENDPOINTS.THR}/posting/generate-monthly`, {
                    method: "POST",
                    headers: {
                      Authorization: `Bearer ${token}`,
                    },
                  });

                  if (res.ok) {
                    const data = await res.json();
                    setGenerateResult(data);
                    toast.success(data.message || "Generate posting THR berhasil");
                    loadTHR();
                    loadStats();
                    setOpenGenerate(false);
                  } else {
                    const err = await res.json();
                    toast.error(err.detail || "Gagal generate posting THR");
                  }
                } catch (err) {
                  console.error("Error generating posting THR:", err);
                  toast.error("Terjadi kesalahan saat generate posting THR");
                }
              }}
              className="bg-green-500 hover:bg-green-600"
            >
              Posting Sekarang
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
