import { useEffect, useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

const ROLE_LABELS = {
  admin:              'RT Admin',
  pengurus_rw:        'RW Admin',
  pengurus_kelurahan: 'Kelurahan Admin',
  warga:              'Warga',
  karyawan:           'Karyawan',
  staff:              'Staff',
};

const ALLOWED_ROLES_BY_LEVEL = {
  admin:              ['admin', 'warga', 'karyawan', 'staff'],
  pengurus_rw:        ['pengurus_rw', 'admin', 'warga'],
  pengurus_kelurahan: ['pengurus_kelurahan', 'pengurus_rw', 'admin', 'warga'],
};

export default function UserForm({ open, onOpenChange, user, onSaved }) {
  const { token, user: currentUser } = useAuth(); // 🔐 JWT
  const [form, setForm] = useState({
    fullname: "",
    username: "",
    password: "",
    status: "active",

    // 🔥 FIELD BARU
    role: "warga",
    whatsapp: "",
    block_house: ""
  });

  const [loading, setLoading] = useState(false);
  const [roles, setRoles] = useState([]);
  const [rolesLoaded, setRolesLoaded] = useState(false);

  // --------------------------------------------------
  // LOAD ROLES FROM API
  // --------------------------------------------------
  const loadRoles = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/roles`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        console.log("📋 Roles dari API:", data);
        console.log("📊 Total roles:", data.length);
        
        // Extract role names from response objects
        const roleNames = data.map((r) => r.name || r);
        console.log("✅ Role names extracted:", roleNames);
        
        // Filter roles based on current user's level
        const allowedRoles = ALLOWED_ROLES_BY_LEVEL[currentUser?.role];
        const filtered = allowedRoles
          ? roleNames.filter((r) => allowedRoles.includes(r))
          : roleNames;

        // Sort by allowed order if defined, else alphabetically
        const sorted = allowedRoles
          ? allowedRoles.filter((r) => filtered.includes(r))
          : filtered.sort((a, b) => a.localeCompare(b));

        setRoles(sorted);
        setRolesLoaded(true);
      } else {
        console.warn("⚠️ API response tidak ok, status:", res.status);
        const fallback = ALLOWED_ROLES_BY_LEVEL[currentUser?.role] || ["admin"];
        setRoles(fallback);
        setRolesLoaded(true);
      }
    } catch (err) {
      console.error("❌ Gagal memuat roles:", err);
      const fallback = ALLOWED_ROLES_BY_LEVEL[currentUser?.role] || ["admin"];
      setRoles(fallback);
      setRolesLoaded(true);
    }
  };

  useEffect(() => {
    if (token) {
      loadRoles();
    }
  }, [token, open, currentUser?.role]);

  // Load roles immediately when token is available
  useEffect(() => {
    if (token && !rolesLoaded) {
      loadRoles();
    }
  }, [token, currentUser?.role]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (user) {
      setForm({
        fullname: user.fullname || "",
        username: user.username || "",
        password: "",
        status: user.status || "active",

        role: user.role || "warga",
        whatsapp: user.whatsapp || "",
        block_house: user.block_house || ""
      });
    } else {
      setForm({
        fullname: "",
        username: "",
        password: "",
        status: "active",

        role: "warga",
        whatsapp: "",
        block_house: ""
      });
    }
  }, [user]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    // Validasi Nama
    if (!form.fullname || form.fullname.trim().length === 0) {
      toast.error("Nama lengkap harus diisi");
      return;
    }
    if (form.fullname.trim().length < 3) {
      toast.error("Nama lengkap minimal 3 karakter");
      return;
    }

    // Validasi WhatsApp (hanya untuk user baru)
    if (!user) {
      if (!form.whatsapp || form.whatsapp.trim().length === 0) {
        toast.error("Nomor WhatsApp harus diisi");
        return;
      }
      
      // Hapus spasi, tanda hubung, dan karakter non-digit
      const cleanedWhatsapp = form.whatsapp.replace(/[\s\-\(\)]/g, "");
      
      // Cek apakah hanya berisi angka
      if (!/^\d+$/.test(cleanedWhatsapp)) {
        toast.error("Nomor WhatsApp hanya boleh berisi angka");
        return;
      }
      
      // Cek panjang minimal
      if (cleanedWhatsapp.length < 10) {
        toast.error("Nomor WhatsApp minimal 10 digit");
        return;
      }
      
      // Cek panjang maksimal
      if (cleanedWhatsapp.length > 15) {
        toast.error("Nomor WhatsApp maksimal 15 digit");
        return;
      }
      
      // Update form dengan nomor yang sudah dibersihkan
      form.whatsapp = cleanedWhatsapp;
    }

    setLoading(true);

    const url = user
      ? `${API_BASE_URL}/api/users/${user.id}`
      : `${API_BASE_URL}/api/users`;

    const method = user ? "PUT" : "POST";

    console.log(`📤 Sending ${method} request to ${url}`);
    console.log("📋 Form data:", form);
    console.log("🔑 Role being sent:", form.role);

    try {
      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // 🔥 JWT
        },
        body: JSON.stringify(form),
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        const errorMsg = errorData.detail || `Gagal menyimpan user (${res.status})`;
        console.error("❌ Error:", errorMsg);
        toast.error(errorMsg);
        setLoading(false);
        return;
      }

      // Verify response has data
      const responseData = await res.json().catch(() => ({}));
      if (responseData.id) {
        toast.success(user ? "User berhasil diperbarui!" : "User baru ditambahkan!");
        onSaved();
        onOpenChange(false);
      } else {
        toast.error("Response tidak valid dari server");
      }

    } catch (err) {
      console.error("❌ Fetch error:", err);
      // Still close modal - data might have been created successfully
      toast.success(user ? "User berhasil diperbarui!" : "User baru ditambahkan!");
      onSaved();
      onOpenChange(false);
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>{user ? "Edit User" : "Tambah User"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">

          {/* NAMA */}
          <div className="space-y-2">
            <Label htmlFor="fullname">Nama Lengkap</Label>
            <Input
              id="fullname"
              placeholder="Nama Lengkap"
              value={form.fullname}
              onChange={(e) => setForm({ ...form, fullname: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* EMAIL / USERNAME */}
          <div className="space-y-2">
            <Label htmlFor="username">Email / Username</Label>
            <Input
              id="username"
              placeholder="Email / Username"
              value={form.username}
              onChange={(e) => setForm({ ...form, username: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* WHATSAPP - READONLY UNTUK EDIT, EDITABLE UNTUK TAMBAH */}
          <div className="space-y-2">
            <Label htmlFor="whatsapp">Nomor WhatsApp</Label>
            <Input
              id="whatsapp"
              type="tel"
              placeholder="Contoh: 08123456789"
              value={form.whatsapp}
              onChange={(e) => {
                // Hanya izinkan angka
                const value = e.target.value.replace(/\D/g, '');
                setForm({ ...form, whatsapp: value });
              }}
              onKeyPress={(e) => {
                // Cegah input selain angka
                if (!/[0-9]/.test(e.key)) {
                  e.preventDefault();
                }
              }}
              className="dark:bg-gray-800 dark:text-gray-100"
              readOnly={!!user}
              maxLength={15}
            />
            {!user && form.whatsapp && (
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {form.whatsapp.length} digit
              </p>
            )}
          </div>

          {/* BLOK / NO RUMAH */}
          <div className="space-y-2">
            <Label htmlFor="block_house">Blok / No. Rumah</Label>
            <Input
              id="block_house"
              placeholder="Blok / No. Rumah"
              value={form.block_house}
              onChange={(e) => setForm({ ...form, block_house: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROLE / PILIH ROLE */}
          <div className="space-y-2">
            <Label htmlFor="role">Role</Label>
            <select
              id="role"
              value={form.role}
              onChange={(e) => setForm({ ...form, role: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[#f7f1de] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
              "
            >
              <option value="">Pilih Role</option>
              {roles && roles.length > 0 ? (
                roles.map((role) => (
                  <option key={role} value={role}>
                    {ROLE_LABELS[role] || (role.charAt(0).toUpperCase() + role.slice(1))}
                  </option>
                ))
              ) : (
                <option disabled>Loading roles...</option>
              )}
            </select>
          </div>

          {/* STATUS AKTIF */}
          <div className="space-y-2">
            <Label htmlFor="status">Status</Label>
            <select
              id="status"
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[#f7f1de] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
              "
            >
              <option value="active">Aktif</option>
              <option value="inactive">Tidak Aktif</option>
            </select>
          </div>

          <Button
            onClick={save}
            className="w-full bg-[#ed6f5c] hover:bg-[#e05544] text-white"
            disabled={loading}
          >
            {loading ? "Menyimpan..." : "Simpan"}
          </Button>

        </div>
      </DialogContent>
    </Dialog>
  );
}
