import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { FileText, RefreshCw, Eye, X, Clock, CheckCircle, XCircle, Search, ChevronLeft, ChevronRight } from 'lucide-react';

const PAGE_SIZE = 10;

const STAT_CARDS = [
  { key: 'total',    label: 'Total Surat',  Icon: FileText,     bg: 'bg-blue-50 dark:bg-blue-900/20',    border: 'border-blue-200 dark:border-blue-800',    iconCls: 'text-blue-500' },
  { key: 'pending',  label: 'Menunggu',     Icon: Clock,        bg: 'bg-amber-50 dark:bg-amber-900/20',  border: 'border-amber-200 dark:border-amber-800',  iconCls: 'text-amber-500' },
  { key: 'approved', label: 'Diterbitkan',  Icon: CheckCircle,  bg: 'bg-green-50 dark:bg-green-900/20',  border: 'border-green-200 dark:border-green-800',  iconCls: 'text-green-500' },
  { key: 'rejected', label: 'Ditolak',      Icon: XCircle,      bg: 'bg-red-50 dark:bg-red-900/20',      border: 'border-red-200 dark:border-red-800',      iconCls: 'text-red-500' },
];

const hdrs = (token) => ({ Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' });

const TAB = { MASUK: 'masuk', TERBIT: 'terbit' };

const STATUS_BADGE = {
  pending:  { label: 'Menunggu',    cls: 'bg-amber-100 text-amber-700' },
  approved: { label: 'Diterbitkan', cls: 'bg-green-100 text-green-700' },
  rejected: { label: 'Ditolak',     cls: 'bg-red-100 text-red-700' },
};

function DetailModal({ open, onClose, item }) {
  if (!open || !item) return null;
  const sc = STATUS_BADGE[item.status] || STATUS_BADGE.pending;
  const fieldData = (() => { try { return JSON.parse(item.field_data || '{}'); } catch { return {}; } })();
  const schema    = (() => { try { return JSON.parse(item.fields_schema || '[]'); } catch { return []; } })();

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <div>
            <h3 className="font-bold text-gray-800 text-lg">{item.jenis_surat}</h3>
            {item.nomor_surat && <p className="text-xs text-gray-500 mt-0.5">No. {item.nomor_surat}</p>}
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          <div className="flex items-center gap-2">
            <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${sc.cls}`}>{sc.label}</span>
            <span className="text-xs text-gray-400">{item.pemohon_nama}</span>
          </div>
          <div className="bg-gray-50 rounded-xl p-4 space-y-2">
            {schema.map(f => (
              <div key={f.id} className="flex gap-3 text-sm">
                <span className="text-gray-500 w-40 flex-shrink-0">{f.label}</span>
                <span className="text-gray-800 font-medium">{fieldData[f.id] || '—'}</span>
              </div>
            ))}
          </div>
          {item.issued_html && (
            <div>
              <p className="text-xs font-medium text-gray-600 mb-2">Preview Surat:</p>
              <iframe srcDoc={item.issued_html} title="preview"
                className="w-full border border-gray-200 rounded-lg" style={{ height: '300px' }} />
            </div>
          )}
          {item.catatan && (
            <div className="bg-red-50 border border-red-200 rounded-xl p-3 text-sm text-red-700">
              Catatan: {item.catatan}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

export default function RWSuratResmi() {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const [activeTab, setActiveTab] = useState(TAB.MASUK);
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [viewItem, setViewItem] = useState(null);
  const [stats, setStats] = useState({ total: 0, pending: 0, approved: 0, rejected: 0 });
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const fetchStats = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (rtId) params.set('rt_id', rtId);
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan?${params}`, { headers: hdrs(token) });
      if (res.ok) {
        const all = await res.json();
        const counts = { total: all.length, pending: 0, approved: 0, rejected: 0 };
        all.forEach(item => { if (item.status in counts) counts[item.status]++; });
        setStats(counts);
      }
    } catch (_) {}
  }, [token, rtId]);

  const fetchData = useCallback(async (status) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (status) params.set('status', status);
      if (rtId) params.set('rt_id', rtId);
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan?${params}`, { headers: hdrs(token) });
      if (res.ok) setData(await res.json());
      else setData([]);
    } catch (_) { setData([]); }
    setLoading(false);
  }, [token, rtId]);

  useEffect(() => { fetchStats(); }, [fetchStats]);

  useEffect(() => {
    fetchData(activeTab === TAB.MASUK ? 'pending' : 'approved');
  }, [activeTab, fetchData]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return data;
    return data.filter(item =>
      (item.pemohon_nama  || '').toLowerCase().includes(q) ||
      (item.jenis_surat   || '').toLowerCase().includes(q) ||
      (item.kode          || '').toLowerCase().includes(q) ||
      (item.tenant_name   || '').toLowerCase().includes(q) ||
      (item.nomor_surat   || '').toLowerCase().includes(q)
    );
  }, [data, search]);

  const totalPages  = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const paginated   = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  useEffect(() => { setPage(1); }, [activeTab, search, data]);

  const openDetail = async (item) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan/${item.id}`, { headers: hdrs(token) });
      setViewItem(res.ok ? await res.json() : item);
    } catch { setViewItem(item); }
  };

  const tabs = [
    { id: TAB.MASUK,  label: 'Permohonan Masuk' },
    { id: TAB.TERBIT, label: 'Surat Terbit' },
  ];

  return (
    <div className="p-6 space-y-5 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Surat Resmi</span>
      </div>

      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
            <FileText className="h-5 w-5 text-white"/>
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Surat Resmi</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Monitoring surat yang diterbitkan RT di bawah RW</p>
          </div>
        </div>
        <button onClick={() => { fetchStats(); fetchData(activeTab === TAB.MASUK ? 'pending' : 'approved'); }}
          className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700">
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`}/>
        </button>
      </div>

      <div className="grid grid-cols-4 gap-4">
        {STAT_CARDS.map(({ key, label, Icon, bg, border, iconCls }) => (
          <div key={key} className={`${bg} border ${border} rounded-2xl p-4 flex items-center gap-3`}>
            <div className="w-11 h-11 rounded-xl bg-white/70 dark:bg-gray-800/50 flex items-center justify-center flex-shrink-0">
              <Icon className={`h-5 w-5 ${iconCls}`}/>
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-800 dark:text-white leading-tight">{stats[key]}</p>
              <p className="text-xs text-gray-500 dark:text-gray-400">{label}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-2xl border border-[#d5cebc] dark:border-gray-700 overflow-hidden">
        <div className="flex items-center justify-between border-b border-[#d5cebc] dark:border-gray-700 px-4">
          <div className="flex">
            {tabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                className={`px-4 py-3.5 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab.id
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                }`}>
                {tab.label}
              </button>
            ))}
          </div>
          <div className="relative py-2">
            <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
            <input
              type="text"
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Cari nama, jenis surat..."
              className="pl-8 pr-3 py-1.5 text-xs border border-[#d5cebc] dark:border-gray-600 rounded-lg bg-white/80 dark:bg-gray-700 focus:outline-none focus:border-blue-400 w-52 text-gray-700 dark:text-gray-200 placeholder-gray-400"
            />
          </div>
        </div>

        <div className="p-4">
          {loading ? (
            <div className="flex justify-center py-12">
              <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"/>
            </div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-12">
              <FileText size={36} className="mx-auto text-gray-300 mb-3"/>
              <p className="text-gray-500 text-sm">
                {search ? 'Tidak ada data yang cocok dengan pencarian' : activeTab === TAB.MASUK ? 'Tidak ada permohonan masuk' : 'Belum ada surat diterbitkan'}
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[#d5cebc] dark:border-gray-700">
                    {['Tanggal', 'Jenis Surat', 'Nama Pemohon', 'RT', 'Status',
                      ...(activeTab === TAB.TERBIT ? ['No. Surat'] : []), 'Aksi'].map(h => (
                      <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#d5cebc] dark:divide-gray-700">
                  {paginated.map(item => (
                    <tr key={item.id} className="hover:bg-[#e4dcc8] dark:hover:bg-gray-700/50">
                      <td className="px-4 py-3 text-gray-500 dark:text-gray-400 text-xs whitespace-nowrap">
                        {new Date(item.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })}
                      </td>
                      <td className="px-4 py-3">
                        <span className="text-xs font-bold px-2 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-400 mr-2">{item.kode}</span>
                        <span className="text-gray-700 dark:text-gray-300">{item.jenis_surat}</span>
                      </td>
                      <td className="px-4 py-3 font-medium text-gray-800 dark:text-gray-200">{item.pemohon_nama}</td>
                      <td className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400">{item.tenant_name || '—'}</td>
                      <td className="px-4 py-3">
                        <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${STATUS_BADGE[item.status]?.cls}`}>
                          {STATUS_BADGE[item.status]?.label}
                        </span>
                      </td>
                      {activeTab === TAB.TERBIT && (
                        <td className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400 font-mono">{item.nomor_surat || '—'}</td>
                      )}
                      <td className="px-4 py-3">
                        <button onClick={() => openDetail(item)}
                          className="flex items-center gap-1 text-xs px-2.5 py-1.5 border border-[#d5cebc] dark:border-gray-600 rounded-lg text-gray-600 dark:text-gray-400 hover:bg-[#d5cebc] dark:hover:bg-gray-700">
                          <Eye size={12}/> Detail
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {filtered.length > 0 && (
            <div className="flex items-center justify-between px-4 pt-3 mt-2 border-t border-[#d5cebc] dark:border-gray-700">
              <p className="text-xs text-gray-500 dark:text-gray-400">
                Menampilkan {Math.min((page - 1) * PAGE_SIZE + 1, filtered.length)}–{Math.min(page * PAGE_SIZE, filtered.length)} dari {filtered.length} data
              </p>
              {totalPages > 1 && (
                <div className="flex items-center gap-1">
                  <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                    className="p-1.5 rounded-lg border border-[#d5cebc] dark:border-gray-600 text-gray-500 hover:bg-[#d5cebc] dark:hover:bg-gray-700 disabled:opacity-30 disabled:cursor-not-allowed">
                    <ChevronLeft size={14}/>
                  </button>
                  {Array.from({ length: totalPages }, (_, i) => i + 1)
                    .filter(p => p === 1 || p === totalPages || Math.abs(p - page) <= 1)
                    .reduce((acc, p, idx, arr) => {
                      if (idx > 0 && arr[idx - 1] !== p - 1) acc.push('…');
                      acc.push(p);
                      return acc;
                    }, [])
                    .map((p, i) => p === '…'
                      ? <span key={`e${i}`} className="px-1.5 text-xs text-gray-400">…</span>
                      : <button key={p} onClick={() => setPage(p)}
                          className={`w-7 h-7 text-xs rounded-lg border transition-colors ${
                            page === p
                              ? 'bg-blue-500 border-blue-500 text-white'
                              : 'border-[#d5cebc] dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:bg-[#d5cebc] dark:hover:bg-gray-700'
                          }`}>{p}</button>
                    )
                  }
                  <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
                    className="p-1.5 rounded-lg border border-[#d5cebc] dark:border-gray-600 text-gray-500 hover:bg-[#d5cebc] dark:hover:bg-gray-700 disabled:opacity-30 disabled:cursor-not-allowed">
                    <ChevronRight size={14}/>
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <DetailModal open={!!viewItem} onClose={() => setViewItem(null)} item={viewItem} />
    </div>
  );
}
