import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { useAuth } from '../../contexts/AuthContext';
import { FileText, Plus, ChevronDown, CheckCircle, Clock, X, AlertTriangle, Eye, Download, RefreshCw } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

const hdrs = (token) => ({ Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' });

const STATUS_CONFIG = {
  pending:  { label: 'Menunggu',   bg: 'bg-yellow-100',  text: 'text-yellow-700' },
  approved: { label: 'Disetujui',  bg: 'bg-green-100',   text: 'text-green-700' },
  rejected: { label: 'Ditolak',    bg: 'bg-red-100',     text: 'text-red-700'  },
};

const WARGA_FIELD_MAP = {
  nama_pemohon:   'nama_lengkap',
  nama_lengkap:   'nama_lengkap',
  nama_warga:     'nama_lengkap',
  nama:           'nama_lengkap',
  tempat_lahir:   'tempat_lahir',
  tanggal_lahir:  'tanggal_lahir',
  jenis_kelamin:  'jenis_kelamin',
  agama:          'agama',
  pekerjaan:      'pekerjaan',
  alamat:         'block_house',
  alamat_lengkap: 'block_house',
  alamat_pemohon: 'block_house',
  no_rumah:       'block_house',
  blok_rumah:     'block_house',
};

function FieldInput({ field, value, onChange, readOnly }) {
  const base = 'w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400';
  const roClass = readOnly ? ' bg-gray-50 text-gray-500 cursor-not-allowed' : '';
  if (field.type === 'select' && field.options?.length) {
    return (
      <select value={value || ''} onChange={e => !readOnly && onChange(e.target.value)}
        className={base + roClass} required={field.required} disabled={readOnly}>
        <option value="">-- Pilih --</option>
        {field.options.map(o => <option key={o} value={o}>{o}</option>)}
      </select>
    );
  }
  if (field.type === 'textarea') {
    return <textarea value={value || ''} onChange={e => !readOnly && onChange(e.target.value)} rows={3}
      className={`${base}${roClass} resize-none`} required={field.required}
      placeholder={field.placeholder || ''} readOnly={readOnly} />;
  }
  return (
    <input type={field.type || 'text'} value={value || ''} onChange={e => !readOnly && onChange(e.target.value)}
      className={base + roClass} required={field.required}
      placeholder={field.placeholder || ''} readOnly={readOnly} />
  );
}

function AjukanModal({ open, onClose, templates, token, user, onSuccess }) {
  const [step, setStep]           = useState(1);
  const [template, setTpl]        = useState(null);
  const [fields, setFields]       = useState({});
  const [nama, setNama]           = useState('');
  const [alamat, setAlamat]       = useState('');
  const [submitting, setSub]      = useState(false);
  const [error, setError]         = useState('');
  const [wargaData, setWargaData] = useState(null);
  const [autoFilled, setAutoFilled] = useState(new Set());

  useEffect(() => {
    if (open) {
      setStep(1); setTpl(null); setFields({}); setError('');
      setAutoFilled(new Set());

      // Langsung isi dari data User (selalu tersedia, tidak perlu fetch)
      const fallbackNama   = user?.fullname || '';
      const fallbackAlamat = user?.block_house || '';
      setNama(fallbackNama);
      setAlamat(fallbackAlamat);

      // Set partial wargaData dari User agar select-template bisa auto-fill nama_pemohon & alamat
      const userFallback = {
        nama_lengkap: fallbackNama,
        block_house:  fallbackAlamat,
        tempat_lahir: null, tanggal_lahir: null,
        jenis_kelamin: null, agama: null, pekerjaan: null,
      };
      setWargaData(userFallback);

      // Coba ambil data Warga lengkap (opsional – untuk tempat_lahir, tanggal_lahir, dll)
      fetch(`${API_BASE_URL}/api/warga/me`, { headers: hdrs(token) })
        .then(res => res.ok ? res.json() : null)
        .then(data => {
          if (data) {
            setWargaData(data);
            setNama(data.nama_lengkap || fallbackNama);
            setAlamat(data.block_house || fallbackAlamat);
          }
        })
        .catch(() => {});
    }
  }, [open, user]);

  // Fungsi auto-fill (useCallback agar stabil sebagai dep)
  const applyAutoFill = useCallback((schemaArr, data) => {
    if (!data) return;
    const newFields = {};
    const newAutoFilled = new Set();
    schemaArr.forEach(f => {
      const prop = WARGA_FIELD_MAP[f.id];
      if (prop && data[prop]) {
        let val = data[prop];
        if (f.id === 'tanggal_lahir' && val) {
          val = f.type === 'date'
            ? new Date(val).toISOString().split('T')[0]
            : new Date(val).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
        }
        newFields[f.id] = val;
        newAutoFilled.add(f.id);
      }
    });
    setFields(prev => ({ ...prev, ...newFields }));
    setAutoFilled(prev => { const s = new Set(prev); newAutoFilled.forEach(id => s.add(id)); return s; });
  }, []); // setFields & setAutoFilled stabil dari useState

  // Re-apply saat wargaData berubah (fetch async selesai setelah template dipilih)
  useEffect(() => {
    if (step !== 2 || !template || !wargaData) return;
    const sc = (() => { try { return JSON.parse(template.fields_schema || '[]'); } catch { return []; } })();
    applyAutoFill(sc, wargaData);
  }, [wargaData]); // intentionally omit step/template/applyAutoFill — closure captures latest values at render time

  if (!open) return null;

  const schema = template ? (() => { try { return JSON.parse(template.fields_schema || '[]'); } catch { return []; } })() : [];

  const selectTemplate = (t) => {
    setTpl(t);
    setStep(2);
    const sc = (() => { try { return JSON.parse(t.fields_schema || '[]'); } catch { return []; } })();
    setFields({});
    setAutoFilled(new Set());
    applyAutoFill(sc, wargaData);
  };

  const namaReadOnly   = !!(nama);
  const alamatReadOnly = !!(alamat);
  const roInputClass  = 'w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm bg-gray-50 text-gray-500 cursor-not-allowed';
  const inputClass    = 'w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSub(true); setError('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/ajukan`, {
        method: 'POST',
        headers: hdrs(token),
        body: JSON.stringify({ template_id: template.id, pemohon_nama: nama, pemohon_alamat: alamat, field_data: fields }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal mengajukan');
      onSuccess(); onClose();
    } catch (e) { setError(e.message); }
    setSub(false);
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <h3 className="font-bold text-gray-800 text-lg">Ajukan Surat Resmi</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>

        {step === 1 ? (
          <div className="p-5 flex-1 overflow-y-auto">
            <p className="text-sm text-gray-500 mb-4">Pilih jenis surat yang ingin Anda ajukan:</p>
            <div className="space-y-2">
              {templates.map(t => (
                <button key={t.id} onClick={() => selectTemplate(t)}
                  className="w-full text-left p-4 border border-gray-200 rounded-xl hover:border-orange-300 hover:bg-orange-50 transition-all group">
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-bold px-2 py-0.5 rounded-md bg-orange-100 text-orange-700">{t.kode}</span>
                        <span className="font-medium text-gray-800 text-sm">{t.jenis_surat}</span>
                      </div>
                      {t.deskripsi && <p className="text-xs text-gray-400 mt-1">{t.deskripsi}</p>}
                    </div>
                    <ChevronDown size={14} className="text-gray-400 group-hover:text-orange-500 -rotate-90" />
                  </div>
                </button>
              ))}
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-5 flex-1 overflow-y-auto space-y-4">
            <div className="flex items-center gap-2 p-3 bg-orange-50 rounded-xl border border-orange-100">
              <span className="text-xs font-bold px-2 py-0.5 rounded-md bg-orange-100 text-orange-700">{template?.kode}</span>
              <span className="text-sm font-medium text-orange-800">{template?.jenis_surat}</span>
              <button type="button" onClick={() => setStep(1)} className="ml-auto text-xs text-orange-500 hover:text-orange-700 underline">Ganti</button>
            </div>

            {error && (
              <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
                <AlertTriangle size={14}/>{error}
              </div>
            )}

            <div>
              <label className="text-sm font-medium text-gray-700 block mb-1">Nama Pemohon *</label>
              <input value={nama} onChange={e => !namaReadOnly && setNama(e.target.value)} required
                className={namaReadOnly ? roInputClass : inputClass}
                placeholder="Nama lengkap sesuai KTP" readOnly={namaReadOnly} />
            </div>
            <div>
              <label className="text-sm font-medium text-gray-700 block mb-1">Alamat Pemohon</label>
              <input value={alamat} onChange={e => !alamatReadOnly && setAlamat(e.target.value)}
                className={alamatReadOnly ? roInputClass : inputClass}
                placeholder="Alamat lengkap" readOnly={alamatReadOnly} />
            </div>

            {schema.map(f => (
              <div key={f.id}>
                <label className="text-sm font-medium text-gray-700 block mb-1">
                  {f.label} {f.required && '*'}
                </label>
                <FieldInput field={f} value={fields[f.id] || ''} readOnly={autoFilled.has(f.id)}
                  onChange={v => setFields(prev => ({ ...prev, [f.id]: v }))} />
              </div>
            ))}

            <div className="flex gap-3 pt-1">
              <button type="button" onClick={() => setStep(1)}
                className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50">Kembali</button>
              <button type="submit" disabled={submitting}
                className="flex-1 bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
                {submitting ? 'Mengajukan...' : 'Kirim Permohonan'}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>,
    document.body
  );
}

function DetailModal({ open, onClose, item }) {
  const [downloading, setDownloading] = useState('');

  if (!open || !item) return null;

  const sc = STATUS_CONFIG[item.status] || STATUS_CONFIG.pending;

  const downloadPDF = async () => {
    if (!item.issued_html) return;
    setDownloading('pdf');
    const div = document.createElement('div');
    div.innerHTML = item.issued_html;
    div.style.cssText = 'position:fixed;left:-9999px;top:0;width:794px;';
    document.body.appendChild(div);
    try {
      const canvas = await html2canvas(div, { scale: 2, useCORS: true });
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgW = 210, imgH = (canvas.height * imgW) / canvas.width;
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, 0, imgW, imgH);
      pdf.save(`${item.nomor_surat?.replace(/\//g, '-') || 'surat'}.pdf`);
    } catch (_) {}
    finally { document.body.removeChild(div); }
    setDownloading('');
  };

  const downloadDOCX = async () => {
    if (!item.issued_html) return;
    setDownloading('docx');
    try {
      const htmlDocx = (await import('html-docx-js/dist/html-docx')).default;
      const blob = htmlDocx.asBlob(`<!DOCTYPE html><html><body>${item.issued_html}</body></html>`);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = `${item.nomor_surat?.replace(/\//g, '-') || 'surat'}.docx`;
      a.click(); URL.revokeObjectURL(url);
    } catch (_) {}
    setDownloading('');
  };

  const fieldData = (() => { try { return JSON.parse(item.field_data || '{}'); } catch { return {}; } })();

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <div>
            <h3 className="font-bold text-gray-800 text-lg">{item.jenis_surat || 'Detail Permohonan'}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div><span className="text-gray-400">Nama Pemohon:</span><p className="font-medium text-gray-800">{item.pemohon_nama}</p></div>
            {item.nomor_surat && <div><span className="text-gray-400">Nomor Surat:</span><p className="font-medium text-gray-800">{item.nomor_surat}</p></div>}
            <div><span className="text-gray-400">Tanggal Ajuan:</span><p className="font-medium text-gray-800">{new Date(item.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}</p></div>
            {item.issued_at && <div><span className="text-gray-400">Tanggal Terbit:</span><p className="font-medium text-gray-800">{new Date(item.issued_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}</p></div>}
          </div>

          {Object.keys(fieldData).length > 0 && (
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Data Permohonan</p>
              <div className="bg-gray-50 rounded-xl p-3 space-y-1.5">
                {Object.entries(fieldData).map(([k, v]) => (
                  <div key={k} className="flex gap-2 text-sm">
                    <span className="text-gray-500 min-w-[120px] capitalize">{k.replace(/_/g, ' ')}:</span>
                    <span className="text-gray-800 font-medium">{v}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {item.catatan && (
            <div className={`p-3 rounded-xl text-sm ${item.status === 'rejected' ? 'bg-red-50 border border-red-100 text-red-700' : 'bg-gray-50'}`}>
              <p className="font-medium mb-0.5">Catatan dari RT:</p>
              <p>{item.catatan}</p>
            </div>
          )}

          {item.issued_html && (
            <>
              <div className="flex gap-2">
                <button onClick={downloadPDF} disabled={!!downloading}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-[#ed6f5c] text-white rounded-xl text-sm font-semibold disabled:opacity-50">
                  <Download size={14}/> {downloading === 'pdf' ? 'Mengunduh...' : 'Download PDF'}
                </button>
                <button onClick={downloadDOCX} disabled={!!downloading}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 border border-blue-300 text-blue-600 rounded-xl text-sm font-semibold hover:bg-blue-50 disabled:opacity-50">
                  <Download size={14}/> {downloading === 'docx' ? 'Mengunduh...' : 'Download DOCX'}
                </button>
              </div>
              <div id="surat-preview-warga" className="border border-gray-200 rounded-xl overflow-hidden">
                <iframe srcDoc={item.issued_html} title="preview" className="w-full" style={{ minHeight: '500px' }} />
              </div>
            </>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

export default function AjukanSurat() {
  const { token, user } = useAuth();
  const [templates, setTemplates] = useState([]);
  const [permohonan, setPermohonan] = useState([]);
  const [loading, setLoading]       = useState(true);
  const [modal, setModal]           = useState(false);
  const [detail, setDetail]         = useState(null);
  const [detailLoading, setDetailLoading] = useState(null);

  const handleViewDetail = useCallback(async (p) => {
    setDetailLoading(p.id);
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan/${p.id}`, { headers: hdrs(token) });
      if (res.ok) setDetail(await res.json());
      else setDetail(p);
    } catch { setDetail(p); }
    setDetailLoading(null);
  }, [token]);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [tRes, pRes] = await Promise.all([
        fetch(`${API_BASE_URL}/api/surat-resmi/templates`, { headers: hdrs(token) }),
        fetch(`${API_BASE_URL}/api/surat-resmi/permohonan`, { headers: hdrs(token) }),
      ]);
      if (tRes.ok) setTemplates(await tRes.json());
      if (pRes.ok) setPermohonan(await pRes.json());
    } catch (_) {}
    setLoading(false);
  }, [token]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const statusCount = { pending: 0, approved: 0, rejected: 0 };
  permohonan.forEach(p => { if (statusCount[p.status] !== undefined) statusCount[p.status]++; });

  return (
    <div className="space-y-5 p-4 sm:p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Ajukan Surat Resmi</h1>
          <p className="text-sm text-gray-500">Ajukan permohonan surat ke RT Anda</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchData} className="px-3 py-2 border border-gray-200 rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
          </button>
          <button onClick={() => setModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] text-white rounded-xl text-sm font-semibold">
            <Plus size={15}/> Ajukan Surat
          </button>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-3">
        {[
          { label: 'Menunggu', count: statusCount.pending, Icon: Clock, bg: 'bg-yellow-50', text: 'text-yellow-700', ic: 'text-yellow-500' },
          { label: 'Disetujui', count: statusCount.approved, Icon: CheckCircle, bg: 'bg-green-50', text: 'text-green-700', ic: 'text-green-500' },
          { label: 'Ditolak', count: statusCount.rejected, Icon: X, bg: 'bg-red-50', text: 'text-red-700', ic: 'text-red-500' },
        ].map(({ label, count, Icon, bg, text, ic }) => (
          <div key={label} className={`${bg} rounded-2xl p-4`}>
            <div className="flex items-center gap-2 mb-1">
              <Icon size={16} className={ic} />
              <span className={`text-xs font-medium ${text}`}>{label}</span>
            </div>
            <p className={`text-2xl font-bold ${text}`}>{count}</p>
          </div>
        ))}
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
        <div className="px-5 py-4 border-b border-gray-100">
          <h2 className="font-semibold text-gray-800">Riwayat Permohonan</h2>
        </div>
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
          </div>
        ) : permohonan.length === 0 ? (
          <div className="py-12 text-center">
            <FileText size={36} className="mx-auto text-gray-300 mb-3"/>
            <p className="text-gray-500 font-medium">Belum ada permohonan</p>
            <p className="text-gray-400 text-sm mt-1">Klik "Ajukan Surat" untuk membuat permohonan baru</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {permohonan.map(p => {
              const sc = STATUS_CONFIG[p.status] || STATUS_CONFIG.pending;
              return (
                <div key={p.id} className="px-5 py-4 hover:bg-gray-50 flex items-center gap-4">
                  <div className="w-9 h-9 bg-orange-100 rounded-xl flex items-center justify-center flex-shrink-0">
                    <FileText size={16} className="text-orange-600" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-800 text-sm truncate">{p.jenis_surat || 'Surat Resmi'}</p>
                    <p className="text-xs text-gray-400">{new Date(p.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}</p>
                  </div>
                  <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
                  <button onClick={() => handleViewDetail(p)} disabled={detailLoading === p.id}
                    className="text-xs px-3 py-1.5 border border-gray-200 rounded-lg hover:bg-blue-50 hover:border-blue-200 hover:text-blue-600 text-gray-500 flex items-center gap-1 disabled:opacity-50">
                    {detailLoading === p.id ? <RefreshCw size={11} className="animate-spin"/> : <Eye size={11}/>} Lihat
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <AjukanModal open={modal} onClose={() => setModal(false)} templates={templates} token={token} user={user} onSuccess={fetchData} />
      <DetailModal open={!!detail} onClose={() => setDetail(null)} item={detail} />
    </div>
  );
}
