import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import { API_BASE_URL } from '../config/api';
import {
  AlertCircle, Plus, Pencil, Trash2, RefreshCw, Eye, Filter, ArrowUpRight
} from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';

const STATUS_COLORS = {
  open: 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20',
  in_progress: 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  resolved: 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
  closed: 'border-gray-400 text-gray-500 bg-[#ece4cf] dark:bg-gray-700',
};

const PRIORITAS_COLORS = {
  rendah: 'border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  sedang: 'border-amber-400 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  tinggi: 'border-red-400 text-red-600 bg-red-50 dark:bg-red-900/20',
  kritis: 'border-red-700 text-red-800 bg-red-100 dark:bg-red-900/40',
  normal: 'border-gray-400 text-gray-600 bg-gray-50 dark:bg-gray-700',
};

const STATUS_LABEL = { open: 'Open', in_progress: 'Proses', resolved: 'Selesai', closed: 'Ditutup' };

const PengaduanPage = () => {
  const { token, user } = useAuth();
  const isWarga = user?.role === 'warga';
  const isAdmin = user?.role === 'admin';

  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterStatus, setFilterStatus] = useState('');
  const [filterKategori, setFilterKategori] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [viewItem, setViewItem] = useState(null);
  const [saving, setSaving] = useState(false);

  const defaultForm = {
    judul: '', deskripsi: '', kategori: 'umum', prioritas: 'normal',
    eskalasi: 'RT', blok_rumah: '', nama_pelapor: '',
    whatsapp_pelapor: '', catatan_penanganan: '', status: 'open',
  };
  const [form, setForm] = useState(defaultForm);

  useEffect(() => { fetchData(); }, [token]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (filterStatus) params.append('status', filterStatus);
      if (filterKategori) params.append('kategori', filterKategori);
      const res = await axios.get(`${API_BASE_URL}/api/pengaduan?${params}`, { headers });
      setData(Array.isArray(res.data) ? res.data : []);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const openAdd = () => {
    setEditItem(null);
    setForm({
      ...defaultForm,
      nama_pelapor: user?.fullname || '',
      eskalasi: isWarga ? 'RT' : 'RT',
    });
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    setForm({
      judul: item.judul, deskripsi: item.deskripsi, kategori: item.kategori,
      status: item.status, prioritas: item.prioritas, eskalasi: item.eskalasi || 'RT',
      blok_rumah: item.blok_rumah || '', nama_pelapor: item.nama_pelapor || '',
      whatsapp_pelapor: item.whatsapp_pelapor || '',
      catatan_penanganan: item.catatan_penanganan || '',
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.judul || !form.deskripsi) return;
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/pengaduan/${editItem.id}`, form, { headers });
      } else {
        await axios.post(`${API_BASE_URL}/api/pengaduan`, form, { headers });
      }
      setShowForm(false);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus pengaduan ini?')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/pengaduan/${id}`, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  const handleEskalasi = async (item) => {
    if (!window.confirm(`Eskalasi pengaduan "${item.judul}" ke RW?`)) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.put(`${API_BASE_URL}/api/pengaduan/${item.id}`, { eskalasi: 'RW' }, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal eskalasi');
    }
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
    : '-';

  const stats = {
    total: data.length,
    open: data.filter(p => p.status === 'open').length,
    in_progress: data.filter(p => p.status === 'in_progress').length,
    resolved: data.filter(p => p.status === 'resolved').length,
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat pengaduan...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RT</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengaduan</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-red-500 to-rose-600 rounded-xl flex items-center justify-center shadow">
            <AlertCircle className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
              {isWarga ? 'Pengaduan Saya' : 'Pengaduan RT'}
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {isWarga ? 'Kirim & pantau pengaduan ke RT' : 'Kelola pengaduan warga di RT ini'}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchData}
            className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors"
          >
            <RefreshCw className="h-4 w-4" />
          </button>
          <button
            onClick={openAdd}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors"
          >
            <Plus className="h-4 w-4" />
            {isWarga ? 'Buat Pengaduan' : 'Tambah Pengaduan'}
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total', value: stats.total, color: 'from-gray-500 to-gray-600' },
          { label: 'Open', value: stats.open, color: 'from-red-500 to-rose-600' },
          { label: 'Dalam Proses', value: stats.in_progress, color: 'from-amber-500 to-orange-600' },
          { label: 'Selesai', value: stats.resolved, color: 'from-green-500 to-emerald-600' },
        ].map((s, i) => (
          <div key={i} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-3">
            <div className={`w-10 h-10 bg-gradient-to-br ${s.color} rounded-lg flex items-center justify-center`}>
              <AlertCircle className="h-5 w-5 text-white" />
            </div>
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">{s.label}</p>
              <p className="text-xl font-bold text-gray-900 dark:text-white">{s.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex flex-wrap gap-3 items-end">
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Status</label>
          <Select value={filterStatus || 'all'} onValueChange={v => { setFilterStatus(v === 'all' ? '' : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Status" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Status</SelectItem>
              <SelectItem value="open">Open</SelectItem>
              <SelectItem value="in_progress">Dalam Proses</SelectItem>
              <SelectItem value="resolved">Selesai</SelectItem>
              <SelectItem value="closed">Ditutup</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Kategori</label>
          <Select value={filterKategori || 'all'} onValueChange={v => { setFilterKategori(v === 'all' ? '' : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Kategori" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Kategori</SelectItem>
              <SelectItem value="infrastruktur">Infrastruktur</SelectItem>
              <SelectItem value="keamanan">Keamanan</SelectItem>
              <SelectItem value="kebersihan">Kebersihan</SelectItem>
              <SelectItem value="sosial">Sosial</SelectItem>
              <SelectItem value="umum">Umum</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <button
          onClick={() => { setFilterStatus(''); setFilterKategori(''); setTimeout(fetchData, 100); }}
          className="px-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 flex items-center gap-1"
        >
          <Filter className="h-3.5 w-3.5" />Reset
        </button>
      </div>

      {/* Table */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Daftar Pengaduan ({data.length})
          </h3>
        </div>
        {data.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Judul</TableHead>
                <TableHead>Kategori</TableHead>
                {!isWarga && <TableHead>Pelapor</TableHead>}
                <TableHead>Prioritas</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Eskalasi</TableHead>
                <TableHead>Tanggal</TableHead>
                <TableHead className="text-center">Aksi</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.map((p) => (
                <TableRow key={p.id}>
                  <TableCell className="font-medium text-gray-900 dark:text-white max-w-[180px]">
                    <span className="truncate block">{p.judul}</span>
                  </TableCell>
                  <TableCell className="text-sm capitalize">{p.kategori}</TableCell>
                  {!isWarga && (
                    <TableCell className="text-sm text-gray-600 dark:text-gray-400">
                      {p.nama_pelapor || '-'}
                    </TableCell>
                  )}
                  <TableCell>
                    <Badge variant="outline" className={PRIORITAS_COLORS[p.prioritas] || ''}>
                      {p.prioritas}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={STATUS_COLORS[p.status] || ''}>
                      {STATUS_LABEL[p.status] || p.status}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={p.eskalasi === 'RW' ? 'border-blue-400 text-blue-600 bg-blue-50' : 'border-gray-300 text-gray-500'}>
                      {p.eskalasi}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                    {formatDate(p.created_at)}
                  </TableCell>
                  <TableCell className="text-center">
                    <div className="flex items-center justify-center gap-1">
                      <button
                        onClick={() => setViewItem(p)}
                        className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded"
                        title="Lihat Detail"
                      >
                        <Eye className="h-3.5 w-3.5" />
                      </button>
                      {isAdmin && (
                        <>
                          <button
                            onClick={() => openEdit(p)}
                            className="p-1.5 text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded"
                            title="Edit"
                          >
                            <Pencil className="h-3.5 w-3.5" />
                          </button>
                          {p.eskalasi !== 'RW' && p.eskalasi !== 'Kelurahan' && (
                            <button
                              onClick={() => handleEskalasi(p)}
                              className="p-1.5 text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded"
                              title="Eskalasi ke RW"
                            >
                              <ArrowUpRight className="h-3.5 w-3.5" />
                            </button>
                          )}
                          <button
                            onClick={() => handleDelete(p.id)}
                            className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"
                            title="Hapus"
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </button>
                        </>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <AlertCircle className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">
              {isWarga ? 'Belum ada pengaduan yang dikirim' : 'Belum ada pengaduan'}
            </p>
          </div>
        )}
      </div>

      {/* Form Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editItem ? 'Edit Pengaduan' : isWarga ? 'Kirim Pengaduan' : 'Tambah Pengaduan'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div>
              <Label>Judul <span className="text-red-500">*</span></Label>
              <Input
                className="mt-1"
                value={form.judul}
                onChange={e => setForm(f => ({ ...f, judul: e.target.value }))}
                placeholder="Judul pengaduan..."
              />
            </div>
            <div>
              <Label>Deskripsi <span className="text-red-500">*</span></Label>
              <Textarea
                className="mt-1" rows={3}
                value={form.deskripsi}
                onChange={e => setForm(f => ({ ...f, deskripsi: e.target.value }))}
                placeholder="Detail pengaduan..."
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Kategori</Label>
                <Select value={form.kategori} onValueChange={v => setForm(f => ({ ...f, kategori: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="infrastruktur">Infrastruktur</SelectItem>
                    <SelectItem value="keamanan">Keamanan</SelectItem>
                    <SelectItem value="kebersihan">Kebersihan</SelectItem>
                    <SelectItem value="sosial">Sosial</SelectItem>
                    <SelectItem value="umum">Umum</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Prioritas</Label>
                <Select value={form.prioritas} onValueChange={v => setForm(f => ({ ...f, prioritas: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="rendah">Rendah</SelectItem>
                    <SelectItem value="normal">Normal</SelectItem>
                    <SelectItem value="sedang">Sedang</SelectItem>
                    <SelectItem value="tinggi">Tinggi</SelectItem>
                    <SelectItem value="kritis">Kritis</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            {/* Status & Eskalasi hanya untuk admin RT */}
            {isAdmin && (
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label>Status</Label>
                  <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v }))}>
                    <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="open">Open</SelectItem>
                      <SelectItem value="in_progress">Dalam Proses</SelectItem>
                      <SelectItem value="resolved">Selesai</SelectItem>
                      <SelectItem value="closed">Ditutup</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Eskalasi</Label>
                  <Select value={form.eskalasi} onValueChange={v => setForm(f => ({ ...f, eskalasi: v }))}>
                    <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="RT">RT</SelectItem>
                      <SelectItem value="RW">RW</SelectItem>
                      <SelectItem value="Kelurahan">Kelurahan</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            )}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Nama Pelapor</Label>
                <Input
                  className="mt-1"
                  value={form.nama_pelapor}
                  onChange={e => setForm(f => ({ ...f, nama_pelapor: e.target.value }))}
                />
              </div>
              <div>
                <Label>Blok Rumah</Label>
                <Input
                  className="mt-1"
                  value={form.blok_rumah}
                  onChange={e => setForm(f => ({ ...f, blok_rumah: e.target.value }))}
                  placeholder="Contoh: A-5"
                />
              </div>
            </div>
            {isAdmin && (
              <div>
                <Label>Catatan Penanganan</Label>
                <Textarea
                  className="mt-1" rows={2}
                  value={form.catatan_penanganan}
                  onChange={e => setForm(f => ({ ...f, catatan_penanganan: e.target.value }))}
                  placeholder="Catatan tindak lanjut..."
                />
              </div>
            )}
          </div>
          <DialogFooter>
            <button
              onClick={() => setShowForm(false)}
              className="px-4 py-2 text-sm border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-800"
            >
              Batal
            </button>
            <button
              onClick={handleSave}
              disabled={saving}
              className="px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg disabled:opacity-50"
            >
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-red-500" />
              {viewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>
                  {STATUS_LABEL[viewItem.status] || viewItem.status}
                </Badge>
                <Badge variant="outline" className={PRIORITAS_COLORS[viewItem.prioritas] || ''}>
                  {viewItem.prioritas}
                </Badge>
                <Badge variant="outline">{viewItem.kategori}</Badge>
                <Badge variant="outline" className={viewItem.eskalasi === 'RW' ? 'border-blue-400 text-blue-600 bg-blue-50' : 'border-gray-300 text-gray-500'}>
                  Eskalasi: {viewItem.eskalasi}
                </Badge>
              </div>
              <div className="grid grid-cols-2 gap-2 text-gray-600 dark:text-gray-400">
                <div><span className="font-medium">Pelapor:</span> {viewItem.nama_pelapor || '-'}</div>
                <div><span className="font-medium">Blok:</span> {viewItem.blok_rumah || '-'}</div>
                <div><span className="font-medium">WA:</span> {viewItem.whatsapp_pelapor || '-'}</div>
                <div><span className="font-medium">Tanggal:</span> {formatDate(viewItem.created_at)}</div>
              </div>
              <div>
                <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Deskripsi:</p>
                <p className="text-gray-600 dark:text-gray-400 bg-[#ece4cf] dark:bg-gray-800 rounded p-3">
                  {viewItem.deskripsi}
                </p>
              </div>
              {viewItem.catatan_penanganan && (
                <div>
                  <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Catatan Penanganan:</p>
                  <p className="text-gray-600 dark:text-gray-400 bg-green-50 dark:bg-green-900/20 rounded p-3">
                    {viewItem.catatan_penanganan}
                  </p>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PengaduanPage;
