import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { vendorConfirm } from './VendorConfirm';
import { Shield, Plus, Edit2, Trash2, X, AlertTriangle, RefreshCw, ChevronDown, ChevronUp, Lock } from 'lucide-react';
import { MENU_ITEMS } from '../../lib/permissionsMatrix';

const SYSTEM_ROLE_NAMES = new Set([
  'pengurus_rt', 'warga', 'pengurus_rw', 'pengurus_kelurahan',
]);

const SYSTEM_ROLE_LEVEL = {
  pengurus_rt:         'RT',
  warga:               'RT',
  pengurus_rw:         'RW',
  pengurus_kelurahan:  'Kelurahan',
};

const LEVEL_COLOR = {
  RT:        'bg-[#fdf1ef] text-[#ed6f5c]',
  RW:        'bg-blue-100 text-blue-700',
  Kelurahan: 'bg-emerald-100 text-emerald-700',
};

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });

// Semua menu diambil dari permissionsMatrix agar selalu sinkron
const GROUP_LABELS = {
  RT:         { label: 'RT (Operasional)',        color: 'bg-[#fdf1ef] text-[#ed6f5c]' },
  RW:         { label: 'RW (Supervisory)',         color: 'bg-blue-100 text-blue-700 '       },
  Kelurahan:  { label: 'Kelurahan (Monitoring)',   color: 'bg-emerald-100 text-emerald-700 ' },
  Vendor:     { label: 'Vendor (Platform)',        color: 'bg-amber-100 text-amber-700 '   },
};

// Kelompokkan MENU_ITEMS berdasarkan group
const MENUS_BY_GROUP = MENU_ITEMS.reduce((acc, item) => {
  if (!acc[item.group]) acc[item.group] = [];
  acc[item.group].push(item);
  return acc;
}, {});

function RoleModal({ open, onClose, onSave, editData }) {
  const [name, setName]     = useState('');
  const [desc, setDesc]     = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  useEffect(() => {
    if (editData) {
      setName(editData.name || '');
      setDesc(editData.description || '');
    } else {
      setName(''); setDesc('');
    }
    setError('');
  }, [open, editData]);

  if (!open) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) { setError('Nama role harus diisi'); return; }
    setSaving(true); setError('');
    try {
      const url    = editData ? `${API_BASE_URL}/api/vendor/roles/${editData.id}` : `${API_BASE_URL}/api/vendor/roles`;
      const method = editData ? 'PUT' : 'POST';
      const res = await fetch(url, {
        method, headers: hdrs(),
        body: JSON.stringify({ name: name.trim(), description: desc }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      onSave(); onClose();
    } catch(e) { setError(e.message); }
    setSaving(false);
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white  rounded-2xl shadow-2xl w-full max-w-md">
        <div className="p-5 border-b border-gray-200  flex items-center justify-between">
          <h3 className="font-bold text-gray-800  text-lg">{editData ? 'Edit Role' : 'Tambah Role Baru'}</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {error && <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600"><AlertTriangle size={14}/>{error}</div>}
          <div>
            <label className="text-sm font-medium text-gray-700  block mb-1">Nama Role *</label>
            <input value={name} onChange={e=>setName(e.target.value)} required
              className="w-full border border-gray-200  rounded-xl px-3 py-2.5 text-sm   focus:outline-none focus:ring-2 focus:ring-violet-500"
              placeholder="contoh: admin, warga, karyawan..." />
          </div>
          <div>
            <label className="text-sm font-medium text-gray-700  block mb-1">Deskripsi</label>
            <input value={desc} onChange={e=>setDesc(e.target.value)}
              className="w-full border border-gray-200  rounded-xl px-3 py-2.5 text-sm   focus:outline-none focus:ring-2 focus:ring-violet-500"
              placeholder="Deskripsi singkat role ini" />
          </div>
          <p className="text-xs text-gray-400 ">
            Setelah role dibuat, atur hak akses melalui menu <span className="font-semibold text-[#ed6f5c]">Hak Akses</span>.
          </p>
          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose}
              className="flex-1 border border-gray-200  rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50">Batal</button>
            <button type="submit" disabled={saving}
              className="flex-1 bg-[#ed6f5c] hover:bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : editData ? 'Simpan' : 'Buat Role'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

export default function VendorRoles() {
  const [roles, setRoles]     = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal]     = useState(false);
  const [editData, setEdit]   = useState(null);
  const [expanded, setExp]    = useState(null);

  const fetchRoles = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/roles`, { headers: hdrs() });
      if (res.ok) setRoles(await res.json());
    } catch(_) {}
    setLoading(false);
  }, []);

  useEffect(() => { fetchRoles(); }, [fetchRoles]);

  const handleDelete = async (id, name) => {
    if (!await vendorConfirm(`Hapus role "${name}"? Tindakan ini tidak dapat dibatalkan.`, 'Hapus Role')) return;
    await fetch(`${API_BASE_URL}/api/vendor/roles/${id}`, { method:'DELETE', headers: hdrs() });
    fetchRoles();
  };

  const getPermCount = (role) => {
    try {
      const p = typeof role.permissions === 'string' ? JSON.parse(role.permissions) : (role.permissions || {});
      // Hitung berdasarkan MENU_ITEMS agar konsisten dengan tampilan dropdown
      return MENU_ITEMS.filter(item => {
        const perms = p[item.id] || {};
        return Object.values(perms).some(Boolean);
      }).length;
    } catch { return 0; }
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 ">Manajemen Role</h1>
          <p className="text-sm text-gray-500">Kelola role dan hak akses pengguna</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchRoles}
            className="px-3 py-2 border border-gray-200  rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading?'animate-spin':''}/>
          </button>
          <button onClick={()=>{setEdit(null);setModal(true);}}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] text-white rounded-xl text-sm font-semibold hover:bg-[#ed6f5c]">
            <Plus size={15}/> Tambah Role
          </button>
        </div>
      </div>

      <div className="bg-white  rounded-2xl border border-gray-100  overflow-hidden">
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
          </div>
        ) : roles.length === 0 ? (
          <div className="py-12 text-center">
            <Shield size={36} className="mx-auto text-gray-300 mb-3"/>
            <p className="text-gray-500 font-medium">Belum ada role</p>
            <button onClick={()=>{setEdit(null);setModal(true);}}
              className="mt-3 px-4 py-2 bg-[#ed6f5c] text-white text-sm rounded-xl hover:bg-[#ed6f5c]">
              Buat Role Pertama
            </button>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {roles.map(role => {
              const permCount = getPermCount(role);
              const isExp     = expanded === role.id;
              let permsObj = {};
              try { permsObj = typeof role.permissions === 'string' ? JSON.parse(role.permissions) : (role.permissions||{}); } catch {}

              const isSystem = role.is_system || SYSTEM_ROLE_NAMES.has(role.name);
              const level    = SYSTEM_ROLE_LEVEL[role.name];

              return (
                <div key={role.id}>
                  <div className="flex items-center gap-3 px-5 py-4 hover:bg-gray-50">
                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 ${isSystem ? 'bg-gray-100 ' : 'bg-[#fdf1ef]'}`}>
                      {isSystem
                        ? <Lock size={15} className="text-gray-500 "/>
                        : <Shield size={16} className="text-[#ed6f5c]"/>}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <p className="font-semibold text-gray-800 ">{role.name}</p>
                        {isSystem && (
                          <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-gray-200  text-gray-500  uppercase tracking-wide">
                            Sistem
                          </span>
                        )}
                        {level && (
                          <span className={`text-[10px] font-semibold px-1.5 py-0.5 rounded ${LEVEL_COLOR[level] || 'bg-gray-100 text-gray-500'}`}>
                            {level}
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-gray-400">{role.description || '—'} · {permCount} menu aktif</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={()=>setExp(isExp?null:role.id)}
                        className="text-xs text-gray-400 hover:text-[#ed6f5c] flex items-center gap-1 px-2 py-1 rounded-lg hover:bg-[#fdf1ef]">
                        Permissions {isExp?<ChevronUp size={12}/>:<ChevronDown size={12}/>}
                      </button>
                      {!isSystem && (
                        <button onClick={()=>{setEdit(role);setModal(true);}}
                          className="p-1.5 text-gray-400 hover:text-[#ed6f5c] hover:bg-[#fdf1ef] rounded-lg">
                          <Edit2 size={14}/>
                        </button>
                      )}
                      {!isSystem && (
                        <button onClick={()=>handleDelete(role.id, role.name)}
                          className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg">
                          <Trash2 size={14}/>
                        </button>
                      )}
                    </div>
                  </div>
                  {isExp && (
                    <div className="px-5 pb-5 bg-gray-50 space-y-4 pt-3">
                      {Object.entries(MENUS_BY_GROUP).map(([group, menus]) => {
                        const grp = GROUP_LABELS[group] || { label: group, color: 'bg-gray-100 text-gray-600' };
                        const activeInGroup = menus.filter(m => {
                          const p = permsObj[m.id] || {};
                          return Object.values(p).some(Boolean);
                        }).length;
                        return (
                          <div key={group}>
                            {/* Group header */}
                            <div className="flex items-center gap-2 mb-2">
                              <span className={`text-[11px] font-semibold px-2.5 py-0.5 rounded-full ${grp.color}`}>
                                {grp.label}
                              </span>
                              <span className="text-[10px] text-gray-400">
                                {activeInGroup} / {menus.length} aktif
                              </span>
                            </div>
                            {/* Menu chips */}
                            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-1.5">
                              {menus.map(item => {
                                const p = permsObj[item.id] || {};
                                const active = Object.values(p).some(Boolean);
                                const crud = [p.read&&'B', p.create&&'T', p.update&&'E', p.delete&&'H'].filter(Boolean).join('');
                                return (
                                  <div key={item.id}
                                    className={`text-xs px-2.5 py-1.5 rounded-lg flex items-center justify-between gap-1 ${
                                      active
                                        ? 'bg-white  border border-[#ed6f5c] [#ed6f5c] text-gray-700  shadow-sm'
                                        : 'bg-gray-100  text-gray-400  border border-transparent'
                                    }`}>
                                    <span className="truncate">{item.label}</span>
                                    {active && (
                                      <span className="text-[9px] font-bold text-[#ed6f5c] flex-shrink-0 bg-[#fdf1ef] px-1 rounded">
                                        {crud}
                                      </span>
                                    )}
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      <RoleModal open={modal} onClose={()=>{setModal(false);setEdit(null);}} onSave={fetchRoles} editData={editData}/>
    </div>
  );
}


