import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { API_BASE_URL } from '../../config/api';
import { FileText, Search, RefreshCw, Eye, Calendar } from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle
} from '@/components/ui/dialog';

const SuratRW = () => {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [viewItem, setViewItem] = useState(null);

  useEffect(() => { fetchData(); }, [token, rtId]);

  const fetchData = async (q = '') => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const p = new URLSearchParams();
      if (rtId) p.append('rt_id', rtId);
      if (q) p.append('search', q);
      const qs = p.toString() ? `?${p}` : '';
      const res = await axios.get(`${API_BASE_URL}/api/rw/letters${qs}`, { headers });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    fetchData(search);
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })
    : '-';

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data surat...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const suratList = data?.data || [];

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Surat</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
            <FileText className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Surat RW</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Histori surat dari RT — {data?.total || 0} surat
            </p>
          </div>
        </div>
        <button onClick={() => fetchData(search)} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
          <RefreshCw className="h-4 w-4" />
        </button>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center">
            <FileText className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">Total Surat</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">{data?.total || 0}</p>
          </div>
        </div>
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-cyan-500 to-blue-600 rounded-xl flex items-center justify-center">
            <Calendar className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">Surat Terbaru</p>
            <p className="text-sm font-semibold text-gray-900 dark:text-white">
              {suratList[0] ? formatDate(suratList[0].created_at) : '-'}
            </p>
          </div>
        </div>
      </div>

      {/* Search */}
      <form onSubmit={handleSearch} className="flex gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Cari judul surat..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <button type="submit" className="px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors">
          Cari
        </button>
        {search && (
          <button type="button" onClick={() => { setSearch(''); fetchData(''); }}
            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 text-sm rounded-lg transition-colors">
            Reset
          </button>
        )}
      </form>

      {/* Table */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Daftar Surat</h3>
          <span className="text-sm text-gray-500 dark:text-gray-400">{suratList.length} surat</span>
        </div>
        {suratList.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Judul Surat</TableHead>
                <TableHead>Dibuat Oleh</TableHead>
                <TableHead>Tanggal Dibuat</TableHead>
                <TableHead>Terakhir Diubah</TableHead>
                <TableHead className="text-center">Aksi</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {suratList.map((s) => (
                <TableRow key={s.id}>
                  <TableCell className="font-medium text-gray-900 dark:text-white max-w-xs">
                    <div className="flex items-center gap-2">
                      <FileText className="h-4 w-4 text-blue-500 flex-shrink-0" />
                      <span className="truncate">{s.judul_surat}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-sm text-gray-600 dark:text-gray-400">
                    {s.creator_name || '-'}
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                    {formatDate(s.created_at)}
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                    {formatDate(s.updated_at)}
                  </TableCell>
                  <TableCell className="text-center">
                    <button
                      onClick={() => setViewItem(s)}
                      className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors"
                      title="Lihat Surat"
                    >
                      <Eye className="h-4 w-4" />
                    </button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <FileText className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Belum ada surat</p>
          </div>
        )}
      </div>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5 text-blue-500" />
              {viewItem?.judul_surat}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="flex gap-4 text-sm text-gray-500 dark:text-gray-400 pb-3 border-b border-[#d5cebc] dark:border-gray-700">
              <span>Dibuat: {formatDate(viewItem?.created_at)}</span>
              <span>Oleh: {viewItem?.creator_name || '-'}</span>
            </div>
            <div
              className="prose dark:prose-invert max-w-none text-sm"
              dangerouslySetInnerHTML={{ __html: viewItem?.isi_surat_html || '' }}
            />
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default SuratRW;
