import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { useAuth } from '../../contexts/AuthContext';
import { FileText, RefreshCw, Eye, X, Search, BarChart3, Settings, Edit2, CheckCircle, AlertTriangle } from 'lucide-react';

const hdrs = (token) => ({ Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' });

const STATUS_CONFIG = {
  pending:  { label: 'Menunggu',    bg: 'bg-yellow-100', text: 'text-yellow-700' },
  approved: { label: 'Diterbitkan', bg: 'bg-green-100',  text: 'text-green-700' },
  rejected: { label: 'Ditolak',     bg: 'bg-red-100',    text: 'text-red-700'  },
};

function DetailModal({ open, onClose, item }) {
  if (!open || !item) return null;
  const sc = STATUS_CONFIG[item.status] || STATUS_CONFIG.pending;
  const fieldData = (() => { try { return JSON.parse(item.field_data || '{}'); } catch { return {}; } })();
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <div>
            <h3 className="font-bold text-gray-800 text-lg">{item.jenis_surat || 'Detail Surat'}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div><span className="text-gray-400">Nama Pemohon:</span><p className="font-medium text-gray-800">{item.pemohon_nama}</p></div>
            {item.nomor_surat && <div><span className="text-gray-400">Nomor Surat:</span><p className="font-medium text-gray-800 font-mono">{item.nomor_surat}</p></div>}
            <div><span className="text-gray-400">Tanggal Ajuan:</span><p className="font-medium text-gray-800">{new Date(item.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}</p></div>
            {item.issued_at && <div><span className="text-gray-400">Tanggal Terbit:</span><p className="font-medium text-gray-800">{new Date(item.issued_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}</p></div>}
            {item.tenant_name && <div><span className="text-gray-400">RT:</span><p className="font-medium text-gray-800">{item.tenant_name}</p></div>}
          </div>
          {Object.keys(fieldData).length > 0 && (
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Data Surat</p>
              <div className="bg-gray-50 rounded-xl p-3 space-y-1.5">
                {Object.entries(fieldData).map(([k, v]) => (
                  <div key={k} className="flex gap-2 text-sm">
                    <span className="text-gray-500 min-w-[130px] capitalize">{k.replace(/_/g, ' ')}:</span>
                    <span className="text-gray-800 font-medium">{v}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          {item.issued_html && (
            <div className="border border-gray-200 rounded-xl overflow-hidden">
              <iframe srcDoc={item.issued_html} title="preview" className="w-full" style={{ minHeight: '480px' }} />
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

function KustomModal({ open, onClose, template, token, onSave }) {
  const [html, setHtml]     = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');
  const [msg, setMsg]       = useState('');

  useEffect(() => {
    if (open && template) {
      fetch(`${API_BASE_URL}/api/surat-resmi/kustom/${template.id}`, { headers: hdrs(token) })
        .then(r => r.ok ? r.json() : null)
        .then(d => { setHtml(d?.override_html_body || ''); setError(''); setMsg(''); });
    }
  }, [open, template, token]);

  if (!open || !template) return null;

  const handleSave = async () => {
    setSaving(true); setError(''); setMsg('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/kustom/${template.id}`, {
        method: 'PUT', headers: hdrs(token),
        body: JSON.stringify({ override_html_body: html || null }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      setMsg('Berhasil disimpan'); onSave();
    } catch (e) { setError(e.message); }
    setSaving(false);
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <div>
            <h3 className="font-bold text-gray-800 text-lg">Kustomisasi Template</h3>
            <p className="text-sm text-gray-500">{template.jenis_surat}</p>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="p-5 flex-1 overflow-y-auto space-y-4">
          {error && <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600"><AlertTriangle size={14}/>{error}</div>}
          {msg && <div className="flex items-center gap-2 bg-green-50 border border-green-200 rounded-lg p-3 text-sm text-green-700"><CheckCircle size={14}/>{msg}</div>}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1">Override Body HTML</label>
            <p className="text-xs text-gray-400 mb-2">Kosongkan untuk menggunakan template default dari vendor. Isi untuk mengganti body surat khusus Kelurahan ini.</p>
            <textarea value={html} onChange={e => setHtml(e.target.value)}
              rows={12} placeholder={template.html_body_template}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-xs font-mono focus:outline-none focus:ring-2 focus:ring-orange-400 resize-none" />
          </div>
          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose}
              className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50">Batal</button>
            <button onClick={handleSave} disabled={saving}
              className="flex-1 bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan Override'}
            </button>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

function TabMonitoring({ token }) {
  const [permohonan, setPermohonan] = useState([]);
  const [loading, setLoading]       = useState(true);
  const [search, setSearch]         = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [detail, setDetail]         = useState(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan`, { headers: hdrs(token) });
      if (res.ok) setPermohonan(await res.json());
    } catch (_) {}
    setLoading(false);
  }, [token]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const filtered = permohonan.filter(p => {
    const matchSearch = !search || p.pemohon_nama?.toLowerCase().includes(search.toLowerCase()) ||
      p.jenis_surat?.toLowerCase().includes(search.toLowerCase()) ||
      p.nomor_surat?.toLowerCase().includes(search.toLowerCase());
    const matchStatus = !filterStatus || p.status === filterStatus;
    return matchSearch && matchStatus;
  });

  const stats = { total: permohonan.length, pending: 0, approved: 0, rejected: 0 };
  permohonan.forEach(p => { if (stats[p.status] !== undefined) stats[p.status]++; });

  const byJenis = permohonan.reduce((acc, p) => {
    acc[p.jenis_surat || 'Lainnya'] = (acc[p.jenis_surat || 'Lainnya'] || 0) + 1;
    return acc;
  }, {});

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button onClick={fetchData} className="px-3 py-2 border border-gray-200 rounded-xl text-sm hover:bg-gray-50">
          <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className="grid grid-cols-4 gap-3">
        {[
          { label: 'Total Surat', count: stats.total, bg: 'bg-blue-50', text: 'text-blue-700' },
          { label: 'Menunggu', count: stats.pending, bg: 'bg-yellow-50', text: 'text-yellow-700' },
          { label: 'Diterbitkan', count: stats.approved, bg: 'bg-green-50', text: 'text-green-700' },
          { label: 'Ditolak', count: stats.rejected, bg: 'bg-red-50', text: 'text-red-700' },
        ].map(({ label, count, bg, text }) => (
          <div key={label} className={`${bg} rounded-2xl p-4`}>
            <p className={`text-xs font-medium ${text} mb-1`}>{label}</p>
            <p className={`text-2xl font-bold ${text}`}>{count}</p>
          </div>
        ))}
      </div>

      {Object.keys(byJenis).length > 0 && (
        <div className="bg-white rounded-2xl border border-gray-100 p-5">
          <div className="flex items-center gap-2 mb-4">
            <BarChart3 size={16} className="text-orange-500" />
            <h3 className="font-semibold text-gray-800 text-sm">Distribusi per Jenis Surat</h3>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
            {Object.entries(byJenis).map(([jenis, count]) => (
              <div key={jenis} className="flex items-center justify-between bg-gray-50 rounded-xl px-3 py-2">
                <span className="text-xs text-gray-600 truncate mr-2">{jenis}</span>
                <span className="text-xs font-bold text-gray-800 bg-white px-2 py-0.5 rounded-full">{count}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
        <div className="px-5 py-4 border-b border-gray-100 flex items-center gap-3">
          <div className="flex-1 relative">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input value={search} onChange={e => setSearch(e.target.value)}
              placeholder="Cari nama, jenis surat, nomor..."
              className="w-full pl-8 pr-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-orange-400" />
          </div>
          <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}
            className="border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400">
            <option value="">Semua Status</option>
            <option value="pending">Menunggu</option>
            <option value="approved">Diterbitkan</option>
            <option value="rejected">Ditolak</option>
          </select>
        </div>

        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
          </div>
        ) : filtered.length === 0 ? (
          <div className="py-12 text-center">
            <FileText size={36} className="mx-auto text-gray-300 mb-3"/>
            <p className="text-gray-500 font-medium">Tidak ada data surat</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50">
                <tr>
                  {['Nomor Surat', 'Jenis Surat', 'Pemohon', 'RT', 'Tanggal', 'Status', 'Aksi'].map(h => (
                    <th key={h} className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filtered.map(p => {
                  const sc = STATUS_CONFIG[p.status] || STATUS_CONFIG.pending;
                  return (
                    <tr key={p.id} className="hover:bg-gray-50">
                      <td className="px-5 py-3">
                        {p.nomor_surat ? <span className="font-mono text-xs text-gray-700">{p.nomor_surat}</span> : <span className="text-gray-400 text-xs">—</span>}
                      </td>
                      <td className="px-5 py-3">
                        <span className="text-xs font-bold px-2 py-0.5 rounded-md bg-orange-100 text-orange-700 mr-1">{p.kode || ''}</span>
                        <span className="text-gray-700">{p.jenis_surat || '—'}</span>
                      </td>
                      <td className="px-5 py-3 text-gray-800">{p.pemohon_nama}</td>
                      <td className="px-5 py-3 text-gray-500 text-xs">{p.tenant_name || '—'}</td>
                      <td className="px-5 py-3 text-gray-500 text-xs">
                        {new Date(p.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })}
                      </td>
                      <td className="px-5 py-3">
                        <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
                      </td>
                      <td className="px-5 py-3">
                        <button onClick={() => setDetail(p)}
                          className="text-xs px-2.5 py-1 border border-gray-200 rounded-lg hover:bg-blue-50 hover:border-blue-300 hover:text-blue-600 text-gray-500 flex items-center gap-1">
                          <Eye size={11}/> Lihat
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="px-5 py-3 border-t border-gray-100 text-xs text-gray-400">
              {filtered.length} dari {permohonan.length} surat
            </div>
          </div>
        )}
      </div>

      <DetailModal open={!!detail} onClose={() => setDetail(null)} item={detail} />
    </div>
  );
}

function TabTemplate({ token }) {
  const [templates, setTemplates]   = useState([]);
  const [loading, setLoading]       = useState(true);
  const [kustom, setKustom]         = useState({});
  const [editTpl, setEditTpl]       = useState(null);

  const fetchTemplates = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-template`, { headers: hdrs(token) });
      if (res.ok) {
        const data = await res.json();
        setTemplates(data);
        const km = {};
        await Promise.all(data.map(async t => {
          try {
            const r = await fetch(`${API_BASE_URL}/api/surat-resmi/kustom/${t.id}`, { headers: hdrs(token) });
            if (r.ok) { const d = await r.json(); if (d?.override_html_body) km[t.id] = true; }
          } catch (_) {}
        }));
        setKustom(km);
      }
    } catch (_) {}
    setLoading(false);
  }, [token]);

  useEffect(() => { fetchTemplates(); }, [fetchTemplates]);

  return (
    <div className="space-y-5">
      <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 text-sm text-blue-700">
        <p className="font-medium mb-1">Tentang Kustomisasi Template</p>
        <p className="text-xs text-blue-600">Kelurahan dapat mengganti isi (body) template surat untuk menyesuaikan dengan format resmi setempat. Template yang tidak dikustomisasi akan menggunakan template default dari vendor.</p>
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
          </div>
        ) : templates.length === 0 ? (
          <div className="py-12 text-center">
            <FileText size={36} className="mx-auto text-gray-300 mb-3"/>
            <p className="text-gray-500 font-medium">Belum ada template</p>
            <p className="text-gray-400 text-sm mt-1">Template dikelola oleh vendor</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50">
                <tr>
                  {['Kode', 'Jenis Surat', 'Status', 'Kustomisasi', 'Aksi'].map(h => (
                    <th key={h} className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {templates.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50">
                    <td className="px-5 py-3">
                      <span className="text-xs font-bold px-2 py-1 rounded-lg bg-orange-100 text-orange-700">{t.kode}</span>
                    </td>
                    <td className="px-5 py-3 font-medium text-gray-800">{t.jenis_surat}</td>
                    <td className="px-5 py-3">
                      <span className={`text-xs px-2 py-1 rounded-full font-medium ${t.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                        {t.is_active ? 'Aktif' : 'Nonaktif'}
                      </span>
                    </td>
                    <td className="px-5 py-3">
                      {kustom[t.id]
                        ? <span className="text-xs px-2 py-1 rounded-full bg-blue-100 text-blue-700 font-medium">Dikustomisasi</span>
                        : <span className="text-xs text-gray-400">Default vendor</span>}
                    </td>
                    <td className="px-5 py-3">
                      <button onClick={() => setEditTpl(t)}
                        className="text-xs px-2.5 py-1 border border-gray-200 rounded-lg hover:bg-[#fdf1ef] hover:border-[#ed6f5c] hover:text-[#ed6f5c] text-gray-500 flex items-center gap-1">
                        <Edit2 size={11}/> Kustomisasi
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <KustomModal open={!!editTpl} onClose={() => setEditTpl(null)} template={editTpl} token={token} onSave={fetchTemplates} />
    </div>
  );
}

function TabProfil({ token }) {
  const [form, setForm] = useState({
    nama_pejabat: '', jabatan: '', no_rt: '', no_rw: '',
    nama_kelurahan: '', kecamatan: '', kabupaten: '', provinsi: '', kota: '',
  });
  const [loading, setLoading]   = useState(true);
  const [saving, setSaving]     = useState(false);
  const [error, setError]       = useState('');
  const [success, setSuccess]   = useState('');

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/surat-resmi/profil`, { headers: hdrs(token) })
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d) setForm(f => ({ ...f, ...d })); setLoading(false); })
      .catch(() => setLoading(false));
  }, [token]);

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true); setError(''); setSuccess('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/profil`, { method: 'PUT', headers: hdrs(token), body: JSON.stringify(form) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      setSuccess('Profil berhasil disimpan');
    } catch (e) { setError(e.message); }
    setSaving(false);
  };

  if (loading) return <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/></div>;

  const fields = [
    { key: 'nama_kelurahan', label: 'Nama Kelurahan', placeholder: 'Kelurahan Sukamaju' },
    { key: 'kecamatan',      label: 'Kecamatan',       placeholder: 'Kecamatan Beji' },
    { key: 'kabupaten',      label: 'Kabupaten/Kota',  placeholder: 'Kota Depok' },
    { key: 'provinsi',       label: 'Provinsi',         placeholder: 'Jawa Barat' },
    { key: 'kota',           label: 'Nama Kota (header surat)', placeholder: 'Depok' },
    { key: 'nama_pejabat',   label: 'Nama Lurah/Pejabat', placeholder: 'Budi Santoso' },
    { key: 'jabatan',        label: 'Jabatan',          placeholder: 'Lurah Sukamaju' },
    { key: 'no_rw',          label: 'Nomor RW (header)', placeholder: '003' },
    { key: 'no_rt',          label: 'Nomor RT (header)', placeholder: '005' },
  ];

  return (
    <div className="max-w-2xl">
      {error && <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600 mb-4"><AlertTriangle size={14}/>{error}</div>}
      {success && <div className="flex items-center gap-2 bg-green-50 border border-green-200 rounded-lg p-3 text-sm text-green-700 mb-4"><CheckCircle size={14}/>{success}</div>}
      <form onSubmit={handleSave} className="bg-white rounded-2xl border border-gray-100 p-5 space-y-4">
        <div className="pb-3 border-b border-gray-100">
          <h3 className="font-semibold text-gray-800">Profil Kelurahan untuk Surat</h3>
          <p className="text-xs text-gray-400 mt-1">Data ini digunakan untuk mengisi header dan footer surat resmi</p>
        </div>
        <div className="grid grid-cols-2 gap-4">
          {fields.map(f => (
            <div key={f.key} className={f.key === 'nama_kelurahan' || f.key === 'kota' ? 'col-span-2' : ''}>
              <label className="text-sm font-medium text-gray-700 block mb-1">{f.label}</label>
              <input value={form[f.key] || ''} onChange={e => setForm(p => ({ ...p, [f.key]: e.target.value }))}
                placeholder={f.placeholder}
                className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400" />
            </div>
          ))}
        </div>
        <button type="submit" disabled={saving}
          className="w-full bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
          {saving ? 'Menyimpan...' : 'Simpan Profil'}
        </button>
      </form>
    </div>
  );
}

export default function KelurahanSuratResmi() {
  const { token } = useAuth();
  const [tab, setTab] = useState('monitoring');

  const TABS = [
    { id: 'monitoring', label: 'Monitoring Surat' },
    { id: 'template',   label: 'Kelola Template' },
    { id: 'profil',     label: 'Profil & Pengaturan' },
  ];

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-bold text-gray-800">Surat Resmi</h1>
        <p className="text-sm text-gray-500">Monitoring dan pengelolaan surat resmi di wilayah Kelurahan</p>
      </div>

      <div className="flex gap-1 bg-gray-100 rounded-xl p-1 w-fit">
        {TABS.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              tab === t.id ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'
            }`}>
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'monitoring' && <TabMonitoring token={token} />}
      {tab === 'template'   && <TabTemplate token={token} />}
      {tab === 'profil'     && <TabProfil token={token} />}
    </div>
  );
}
