import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { API_ENDPOINTS } from '@/config/api';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from '@/components/ui/sonner';

export default function FundForm({ open = false, onClose = () => {}, editFund = null }){
  const { token } = useAuth();
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [monthly, setMonthly] = useState(0);
  const [desc, setDesc] = useState('');
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    const loadCats = async () => {
      try {
        const res = await fetch(API_ENDPOINTS.FINANCE_CATEGORY, { headers: { Authorization: `Bearer ${token}` } });
        if (res.ok) setCategories(await res.json());
      } catch (err) { console.error(err); }
    };
    if (token) loadCats();
  }, [token]);

  // Prefill for edit
  useEffect(() => {
    if (editFund) {
      setName(editFund.fund_name || '');
      setCategory(editFund.finance_category_id || '');
      setMonthly(editFund.monthly_amount || 0);
      setDesc(editFund.description || '');
    } else {
      setName(''); setCategory(''); setMonthly(0); setDesc('');
    }
  }, [editFund, open]);

  const [saving, setSaving] = useState(false);

  const handleSubmit = async () => {
    if (!name) return toast.error('Nama dana harus diisi');
    setSaving(true);
    try {
      let res, payload;
      if (editFund) {
        res = await fetch(`${API_ENDPOINTS.DANA_FUNDS}/${editFund.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({ fund_name: name, finance_category_id: category || null, monthly_amount: Number(monthly), description: desc, is_active: true })
        });
      } else {
        res = await fetch(API_ENDPOINTS.DANA_FUNDS, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({ fund_name: name, finance_category_id: category || null, monthly_amount: Number(monthly), description: desc })
        });
      }
      payload = await res.json().catch(() => ({}));
      if (res.ok) {
        toast.success(editFund ? 'Dana berhasil diupdate' : 'Dana berhasil disimpan');
        onClose();
      } else {
        toast.error(payload.detail || 'Gagal menyimpan dana');
        console.error('Save dana error:', payload);
      }
    } catch (err) {
      console.error(err);
      toast.error('Terjadi kesalahan saat menyimpan dana');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{editFund ? 'Edit Dana' : 'Tambah Dana Baru'}</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <div>
            <Label>Nama Dana</Label>
            <Input value={name} onChange={(e) => setName(e.target.value)} />
          </div>
          <div>
            <Label>Kategori Sumber Dana</Label>
            <Select value={category} onValueChange={(v) => setCategory(v)}>
              <SelectTrigger><SelectValue placeholder="-- Pilih --" /></SelectTrigger>
              <SelectContent>
                {categories.map(c => (
                  <SelectItem key={c.id} value={c.id}>{c.nama}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>Alokasi Bulanan</Label>
            <Input type="number" value={monthly} onChange={(e) => setMonthly(Number(e.target.value) || 0)} />
          </div>
          <div>
            <Label>Deskripsi</Label>
            <Input value={desc} onChange={(e) => setDesc(e.target.value)} />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSubmit} className="bg-[#ed6f5c]" disabled={saving}>{saving ? 'Menyimpan...' : 'Simpan'}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
